// 第 151—167 节：依据德文底本自译；讲解与补充比较为本站编写。
(() => {
  const add = (lesson, essay) => { window.LESSONS.push(lesson); window.ESSAYS[lesson.id] = essay; };
  add({id:151,short:'突然理解的几种经过',title:'“现在我会了”，究竟发生了什么？',subtitle:'从找公式、看差数到认出熟悉数列，比较突然理解的不同经过。',tags:['理解','数列','体验'],connection:'第 150 节把知道与能够联系；本节考察能力突然出现的说法；第 152 节追问这些经过是否就是理解。',translation:['不过，“知道”这个词也有这样的用法：我们说“现在我知道了！”——同样也说“现在我会了！”和“现在我理解了！”','设想这个例子：A 写下一列数；B 看着，试图在数的顺序中找出一个规律。成功时，他喊道：“现在我能继续了！”——所以，这种能力、这种理解，是在某个瞬间出现的。那就来看：这里出现的是什么？假定 A 写了 1、5、11、19、29；B 说，现在他知道怎样往下写了。发生了什么？可能发生过种种不同的事情。例如：A 慢慢地一个接一个写数时，B 忙着在这些数上试用不同的代数公式。当 A 写到 19，B 试了公式 aₙ = n² + n − 1；下一个数证实了他的猜测。','或者，B 不想公式。他带着某种紧张感看 A 写数，脑中浮动着种种模糊的想法。最后他问自己：“差数的数列是什么？”他发现是 4、6、8、10，并说：现在我能继续。','或者，他看着说：“啊，这个数列我认识。”然后继续写，正如 A 写出 1、3、5、7、9 时他也可能做的那样。或者，他什么也不说，只把数列接着写下去。也许他有一种可叫作“这很容易！”的感觉。（例如，轻而短促地吸一口气，类似轻微受惊时的感觉。）']},{core:'第 151 节承认“现在我理解了”可以标记一个转折，但这个转折能够伴随不同过程：找到公式、看出差数、认出熟悉的排列，甚至不说话就继续。作者用这些差别阻止我们过早把一种常见经历选成理解本身。',coreMore:'这里不是要求学习者先有相同内心体验才算理解，而是摆出“现在会了”实际可以出现的几种场合。能力有获得的时刻，与理解是一种固定的瞬间心理事件，并非同一句话。下一节才直接追问这些经过是否足够构成理解。',closeReading:[['现在我能继续了！','这句话既带着时间标记，又指向后续行动。“现在”报告转折，“能继续”则涉及尚未实际写出的数。若只盯住感到豁然的瞬间，就会漏掉这项面向继续的承诺。作者从这里展开问题，而没有先规定理解必定是什么。'],['可能发生过种种不同的事情。','这一句决定列举的作用。后面几种经过不是寻找唯一机制的连续淘汰赛，而是提醒我们相同说法可以适合不同经过。找到公式并非唯一候选；没有清楚公式，也不能直接判定没有理解。'],['下一个数证实了他的猜测。','这里的证实属于当事人尝试公式的过程，不是证明有限数列只有唯一延长法。公式在第一项取序号一时给出一，随后给出五、十一、十九、二十九。它提供一种熟悉的继续方式；不能由五项相合推出任何可能规则都已被排除。'],['或者，他什么也不说，只把数列接着写下去。','理解的场合不必以宣告和明确自我观察为中心。一个人可以直接继续，旁人也可能据其学习背景与后续表现说他懂了。这里没有说所有无言动作都是理解，而是取消说出一句心理报告才算理解的限制。']],problem:['第 150 节强调知道与能力的联系，反对者现在可以指出：能力似乎持续存在，然而人又确实会在某一刻喊“懂了”。如果把能力与瞬间看成互斥选项，我们便可能觉得只能退回隐藏心理过程。作者保留这种突然获得的说法，转而调查它出现时到底有什么。','看公式的例子有具体顺序：B 先尝试几种代数式，在十九出现时采用一个公式，再由二十九加强猜测。这个过程不是纯粹凝视内心，而包含观察、试算与调整。把整段描述压成“一道灵光”，就丢掉了使“现在会了”在这里可理解的安排。','差数路线与公式路线在数学上有关，却不要求当事人经历完全相同。B 可以先注意连续差的递增，也可以仅认出曾学过的类型。本节关心的不是列出全部发现算法，而是让几种不同经历并列，从而检查我们为什么想把理解固定在其中一个上。'],conceptTitle:'获得能力的时刻与一种固定体验',concepts:['“突然理解”可以标记从不会继续到会继续的转折。它不必指一项与疼痛、听旋律同样具有可直接描述时程的心理事件。一个人何时开始会某种技能，和他那一刻胸口有什么感觉，是可以分开问的两个问题；后者即使回答清楚，也未必完成前者的说明。','本节末尾的吸气感觉尤其容易误导。作者不是找到了理解的生理印记，而是在展示可能伴随理解的一项细节。若其他人没有吸气，或有人吸气却无法继续，理解的判断不能因此简单颠倒。这个例子为第 152 节区分伴随过程与理解准备材料。'],table:{headers:['可能经过','当事人的线索','不能直接推出'],rows:[['试用代数公式','下一项与猜测相合','公式出现就是理解'],['观察差数递增','四、六、八、十的排列','每次都必须走这条路线'],['认出或直接继续','熟悉背景与后续行动','理解必须伴随自述']]},argument:['先承认“现在知道了”的日常说法，避免为了能力观点而删除真实用法。时间上的突然获得是需要说明的材料，不是应当否认的反例。','再在相同数列上更换经过，使一个共同结论与多个不同背景并列。比较让“大家都懂同一规则，所以心中必有同一种事件”的推断失去当然性。','最后保留身体感觉这种最像私人瞬间的候选，却不给它最后裁判权。下一节将询问：即使公式或感觉出现，一个人是否仍可能没有理解。'],opposition:['本节反对从一句突然理解的宣告直接推出一个唯一的内部构成。我们知道转折发生，并不等于已经知道转折必须由何种心理事件来定义。','它也没有否定思考过程的存在或研究价值。公式尝试、紧张和认出都被明确描述；需要限制的是把其中任意一项独自提升为理解的必要充分条件。'],perspectives:[['从学习过程看','不同学习者可以通过不同路径获得继续的能力。本站的教学提示是，解释时应区分找出公式、辨认差数与稳定使用的表现，不应仅因路径不同就否定掌握。'],['从数学例子看','有限初项可适合多种延长。这里的公式属于例子中的具体发现过程，不能被误读为作者证明了前五项在逻辑上强迫唯一无限序列。'],['从哲学方法看','作者不先回答“理解究竟是什么物”，而是让同一说法在几种场合工作。对比本身揭示我们原来把不同问题挤进一个瞬间的倾向。']],cautions:[['不是所有理解都必须突然发生','本节选择突然知道的用法来讨论，并没有把它普遍化。有些掌握逐渐形成，时间边界也可能不清楚。'],['不是有公式就必定会继续','公式还需要应用。第 152 节正要利用可能想到公式却不懂的情况检验本节候选，不能在这里提前取消那个问题。'],['不要把吸气当作理解测试','吸气只是可能伴随的体验。把它写成识别理解的身体指标，会把列举的材料误当成作者的理论结论。']],summary:'“现在懂了”可以有多种具体经过，理解不能未经检查就等同于其中一个瞬间体验。'});
  add({id:152,short:'伴随理解并不是理解',title:'想到公式，为什么还可能没有懂？',subtitle:'区分一种典型经过与理解本身。',tags:['理解','公式','伴随过程'],connection:'第 151 节列举突然理解的经过；本节检查这些经过是否足够；第 153 节展示寻找隐藏过程的困境。',translation:['可是，我刚才描述的这些过程，就是理解吗？“B 理解数列的系统”，显然不只是说：B 想到了公式“aₙ = ……”！因为完全可以设想，他想到了公式，却仍不理解。“他理解”必须包含比“他想到了公式”更多的东西。同样，也必须包含比任何一种或多或少典型的理解的伴随过程或表现更多的东西。']},{core:'第 152 节指出，想到公式可以伴随理解，却不能独自等于理解。我们能够设想公式出现而当事人并不懂，所以不能拿一项常见的经过代替“理解”这一判断的全部内容。',coreMore:'这里的“更多”暂未指定另一项隐藏事物。作者正要检查：从伴随过程不足，是否就该推断背后另有一个独立心理过程。把“更多”立即当成隐藏实体，会直接跌入下一节的迷乱。',closeReading:[['这些过程，就是理解吗？','提问回指上一节的试公式、看差数、认出和感觉。它不是怀疑这些事情能否发生，而是问它们在概念上担任何种角色。一次经过的真实记录，不会自动成为理解的定义。'],['他想到了公式，却仍不理解。','这是检验等同说的关键对照。一个人可能记起表达式，却不知道符号如何对应序号，或不知道怎样继续计算。本站补充这些可能细节，是为了说明想到与会用之间仍有需要交代的联系。'],['必须包含比“他想到了公式”更多的东西。','“更多”首先表示这两种说法不能简单互换，并非宣布理解由公式事件再加一个神秘事件组成。若把差别改写成内部零件的数量，就提前接受了尚在审查的模型。'],['理解的伴随过程或表现','伴随可以十分典型，也可以帮助我们识别场合；典型不等于独自充分。一个熟悉表情、一个脱口而出的公式，都需要放回能力、学习和继续的背景中才获得这里的分量。']],problem:['上一节故意给出不同的发生经过。现在若有人选出“公式浮现”作为理解，作者便要求考虑这种浮现与实际不会应用能够并存的情况。这个检查防止我们只因某种经历很鲜明，就把概念的全部工作交给它。','重要的是，同样的经历并不能无条件担保同样的理解。一个人说出正确公式，可能是在机械背诵，也可能已掌握应用；我们需要继续问情境与后续，而不是仅重复描述那一个瞬间。','反向推论也要小心。公式不是充分条件，不等于公式对理解从无帮助。理解过程可以利用公式，问题只在于是否已经把一项工具或表现当成理解的全部。这个区分保留了数学学习的具体工作。'],conceptTitle:'“更多”为什么不必是更多内部零件',concepts:['一个判断涉及更多条件，可以意味着它依靠更广的使用背景，而非描述更多同时发生的心理事件。例如，本站补充：“他已学会开车”不同于“他此刻转动方向盘”，但差别不要求每次转动都额外伴随一项叫作会开车的意识活动。','伴随现象的地位也不应被贬为毫无意义。教师可以通过公式、提问和继续作答了解学生的掌握情况。需要纠正的是把某次表征从这些关系中切下，再赋予它不受背景影响的最终裁决权。'],table:{headers:['观察到的事情','可能的作用','不足以独自保证'],rows:[['想到公式','提供继续的线索','已经知道怎样应用'],['出现轻松感','标记当事人的转折','后续不会出错'],['说“我懂了”','表达确信和准备','所有条件均已满足']]},argument:['先把上一节的事件重新摆成候选，询问它们与理解能否等同。','再用想到公式却不会应用的可能场合打断简单等号。反例针对充分性，而不是否定公式存在。','最后把同样的检查扩展到其他伴随表现。理解需要更多说明，但本节尚未给这个更多指定隐藏的地址。'],opposition:['反对把一个醒目而常见的心理事件当成理解本身。相伴发生不能取代对于词语使用条件的说明。','也反对因此认定理解完全没有心理伴随。作者承认伴随过程，所限制的是它们独自定义理解的权利。'],perspectives:[['从数学学习看','会写公式与会将它用于新项需要区别。本站补充的教学视角是，检查应当继续到应用，而不是停在复述表达式。'],['从概念关系看','两个描述不等义，不必意味着它们各自命名了一个内在对象。差别可以体现在各自允许的推断与应用条件上。'],['从论证位置看','这一节保留“更多”的开放性，下一节将显示把它理解成幕后过程怎样造成迷路。前后顺序不能倒转。']],cautions:[['不是说公式可有可无','某些理解正借公式建立。本节没有取消它的作用，只是否定出现公式便已完成全部判断。'],['不是必须无限考试','需要背景并不意味着任何判断都要无穷验证。具体场合中可以已有足够根据，作者在检查根据属于什么。'],['不是已经找到隐藏理解','“更多”是一项区分，不是另一个内在实体的名称。不要用尚未解释的东西替代已经说明不足的东西。']],summary:'公式的浮现可以伴随理解，但它与理解之间不能直接画上等号。'});
  add({id:153,short:'隐藏的理解往哪里找',title:'如果理解藏着，我们怎么知道在找什么？',subtitle:'让“幕后心理过程”的搜索暴露自己的困难。',tags:['理解','隐藏过程','哲学困惑'],connection:'第 152 节说伴随过程不足；本节展示把不足补成隐藏过程的混乱；第 154 节将改问使用的情境。',translation:['我们现在试图抓住理解这一心理过程：它似乎藏在那些较粗糙、因而更引人注意的伴随现象背后。但我们没有成功。或者，更准确地说，根本还没有真正开始尝试。因为，即便假定我找到某种在所有那些理解场合都会发生的东西，为什么它就应当是理解呢？而且，如果我说“现在我理解了”，正是因为我理解了，那么理解的过程又怎么可能是隐藏的呢？如果我说它是隐藏的，我又怎么知道自己该找什么？我陷入了一团混乱。']},{core:'第 153 节把寻找理解本身的计划推到困难处：如果理解是一项隐藏过程，凭什么辨认找到的东西就是理解？我们已经使用“我理解了”，却又把使这句话成立的东西设成原则上尚待搜寻的幕后对象。',coreMore:'作者不是报告一次失败的心理实验，而是在追问搜索任务有没有被说明。即使发现一种共同发生的东西，也还需要交代为何它构成理解，不能把相关性直接当成概念身份。',closeReading:[['根本还没有真正开始尝试。','问题不只是观察设备不够精密，而是“所寻找的是什么”尚未明确。没有辨认标准，增加一种观察结果仍未说明应当把什么结果接受为理解。'],['在所有那些理解场合都会发生的东西','共同发生只提供一种候选联系。即便某脑活动总与成功答题同时出现，也还要说明研究如何识别理解场合。本站这个科学比较不否定实验价值，只区分相关发现与词义解释。'],['为什么它就应当是理解呢？','这一问切断从普遍伴随到本质等同的跳跃。上一节说伴随不够，并没有授权我们把较隐蔽的伴随直接升级为理解。隐蔽性本身不给候选增加概念资格。'],['我又怎么知道自己该找什么？','作者把自己的提问也变成材料。若我能在日常中说懂了，就值得检查这种说法怎样使用；若坚持只有发现隐藏对象才算懂，又得解释搜索目标如何获得。冲突发生在这两种要求之间。']],problem:['把理解当作心理过程，容易形成一个内部舞台：公式、紧张和轻松在前台，真正理解躲在幕后。这个画面看似给“更多”找到了地址，实际上还没有说明幕后对象的辨认方式。','一个共同机制即便被发现，也未必解决这里的哲学问题。研究者需要先凭某些场合与表现，把实验对象分为理解和不理解；这份先行工作不能再全部交给尚未发现的机制。否则研究的标记与机制的身份互相等待。','第一人称句子让混乱更明显。当事人并不是每次先检查一个隐藏过程，然后才有根据说理解。他能直接说“现在我会继续”，这一正常用法与哲学上必须先定位过程的要求，需要被分开考察。'],conceptTitle:'搜索失败与搜索任务尚未形成',concepts:['搜索任务形成，需要说明什么算找到、什么算没有找到。这里缺少的不是一个名字，而是名字的工作方式。叫它“理解过程”并不能替代这项说明，正如给未知物写一个标签，并不已经提供辨认它的方法。','这段自述中的混乱具有方法意义。作者不是把自己摆在不会出错的位置，而是展示一种思路怎样把自己逼进角落。读者可以跟随这些转折，检查是哪一步把熟悉用法转换成无法完成的对象搜索。'],table:{headers:['搜索中的要求','出现的困难','可继续检查'],rows:[['理解应藏在伴随后面','何谓后面尚不清楚','这幅画面如何形成'],['共同发生就是理解','身份没有被说明','伴随与标准的区别'],['先找到才知道懂了','与实际宣告的用法冲突','何种情境使宣告成立']]},argument:['先暂时沿着隐藏过程的想象走，保留它表面上的吸引力。','再即使让搜索成功，追问所发现者为何被认作理解。问题于是显出并非纯粹设备不足。','最后把日常“我懂了”的使用与哲学搜索要求并列，让两者的不协调为下一节的改问提供动力。'],opposition:['反对把隐藏性当作解释力。一个东西越不可见，并不因此越有资格担任理解的本质。','不反对研究脑过程或学习机制。那些研究可以提出可检验假说；本节检查的是未交代辨认标准就声称已经指定理解本身的做法。'],perspectives:[['从方法看','澄清有时先要取消一个假装已经明确的搜索目标。这样做不是逃避研究，而是使任务有可辨认的条件。'],['从自我认识看','直接说理解的用法不宜被改写成对内部装置的观察报告。否则我们会为正常宣告虚构一套先行检验。'],['从科学说明看','机制解释与概念考察可以相互关联，但不能互相吞并。概念区分告诉我们研究什么，经验结果则回答具体机制怎样工作。']],cautions:[['不是隐藏事物都不存在','许多机制可以被间接发现。批评针对的是某个搜索计划的说明空缺，而非一切不可见对象。'],['不是理解纯属幻觉','混乱的是把理解当成隐藏对象的要求；我们实际学习和继续的活动没有因此消失。'],['不是一种反科学立场','作者没有比较不同实验假说的优劣，而是检查为什么某种哲学解释让我们不知道该找什么。']],summary:'在追问理解藏在哪里以前，先检查“找到理解”究竟被设定成什么任务。'});
  add({id:154,short:'回到使宣告成立的情境',title:'不是另一个过程，而是怎样的情境？',subtitle:'把“理解在幕后”的画面改成对使用条件的考察。',tags:['理解','情境','标准'],connection:'第 153 节显示隐藏过程的搜索困境；本节改问何种情况使“我能继续”成立；第 155 节压缩这个区别。',translation:['可是，停一下！——如果“现在我理解这个系统了”与“我想到了公式……”（或“我说出公式”“我写下公式”等等）并不是同一句话的意思，难道由此就能推出：我把“现在我理解……”或“现在我能继续”用作对一个过程的描述，而这个过程存在于说出公式的过程背后或旁边吗？','如果一定要有什么处在“说出公式的背后”，那就是某些情境：当公式浮现时，这些情境使我有理由说，我能继续。','试着完全不要把理解想作“心理过程”！——因为使你混乱的正是这种说法。要问：究竟在什么场合、什么情境下，我们说“现在我知道怎样继续”？我是说，在公式浮现时。','在理解有其典型过程——也包括心理过程——的那个意义上，理解不是一个心理过程。','（痛感的增强与减弱、听见一段旋律或一个句子：这些是心理过程。）']},{core:'第 154 节转变提问：理解不同于公式浮现，不等于公式旁边还必须有另一个事件。需要考察的是，在怎样的学习、应用和继续背景中，我们才有理由把公式的出现称为理解。',coreMore:'“理解不是心理过程”在本节有明确限定：它不是以疼痛起伏、听到旋律那样的事件方式来起作用。这句话没有否认人有内心活动，而是防止把能力与宣告的条件误装成一个并行事件。',closeReading:[['难道由此就能推出','开头是在审查一个推论。两个表达不等义，不保证它们各自描述一个并列过程。“现在有资格参加”和“现在拿到纸张”不同，也不必多出另一项感觉。本站这个比较说明推论形式，不替原文定义理解。'],['那就是某些情境','这里对“背后”作了转向：不再沿空间想象往心内退，而是展开使说法成立的条件。情境可以包括以前的教学和后续应用，不能都压缩成同一时刻头脑里的一件东西。'],['在什么场合、什么情境下','问法把注意力交还给实际用法。它不要求列出一套适用所有理解的万能清单，而是从这里的数列场景出发，弄清为什么这些人会接受或修正理解的宣告。'],['理解不是一个心理过程','这一句必须连着前面的限定读。理解能够有典型的心理伴随，却不因此与某一种伴随同类。把它摘成“理解与心理毫无关系”，会取消作者明确承认的那些过程。']],problem:['第 152 节的“更多”很容易被看成再加一件心理事件。本节说明这不是必要结论。我们需要更多条件，未必需要多出一个对象；对象模型正是前一节越找越混乱的来源。','公式在不同背景下具有不同分量。一个熟练学生想到公式后会试算和继续，另一个人可能只记住字形。本站补充这一对照，是说明同样一句公式怎样在不同能力背景中被评价，而不是给理解设一次表现的机械测试。','情境并非笼统借口。可以追问教学到了什么程度、符号怎样解释、当事人如何处理下一项，以及何种回应会让宣告失去根据。这样的问题虽不保证永远没有争议，却比“真正事件在哪里”更能展开可检查的差别。'],conceptTitle:'条件的增多与事件的增多',concepts:['一个行为取得某种地位，可以依靠过去和未来的联系。本站补充：同样一次签名，是否构成批准，要看职权、文件和程序，不需同时出现一种叫作批准的额外身体动作。理解的情境考察与这个比较有相似点，但并不意味着理解就是制度行为。','心理过程的例子展示另一种语法：疼痛可以增强、减弱并有持续时程，旋律可以开始和结束。掌握一种技术时也会发生心理过程，但“会不会”并不总按同一种时程提问。原文通过相邻概念的差别来解除混同。'],table:{headers:['原先想象','改问后的材料','避免的混淆'],rows:[['公式之后另有理解事件','公式在何种背景中出现','不等义不等于多一事件'],['向内寻找更细过程','教学与应用怎样接续','条件不都在同一瞬间'],['理解是特殊体验','能力与心理伴随的关系','有体验不等于就是体验']]},argument:['先撤回从两句话不同到两件事件并列的推论，让“更多”的解释重新开放。','然后把背后换成情境，考察学习经历、使用与继续怎样为宣告提供根据。','最后用心理过程的普通例子限定否定句的范围，避免从概念差别滑向否认心理生活。'],opposition:['反对把一切有区别的说法都当成不同对象的名称。概念差别可以体现为使用条件，而不是内在舞台上的额外演员。','也反对以情境为名停止说明。指出情境只是研究方向，仍需展示哪个具体联系对这个理解判断有作用。'],perspectives:[['从语言使用看','“我会了”有宣告能力的作用，不能仅按报告一个感觉来解释。它面向可继续的活动，因而可以受到后续表现的修正。'],['从教育看','同一句提示对不同学生可能有不同效果。理解提示的条件包括既有技能，因此教学不能只比较提示当下的字面形式。'],['从哲学治疗看','方法的变化在问句中发生。原来寻找对象的追问，被改造成对熟悉条件的安排；这让前节的混乱得到可继续的出口。']],cautions:[['不是只允许外部行为','情境可以包括心理过程；作者否定的是把理解与某项过程等同，不是给可讨论材料划内外禁区。'],['不是理解等于他人认可','共同评价的条件重要，但认可本身可能出错。本节并未提出多数人同意便构成理解的原则。'],['不要删除否定句的限定','“在那个意义上”限制了心理过程的说法。读成理解毫无心理成分，会与本节对典型心理过程的承认冲突。']],summary:'理解不同于公式浮现，所需展开的可以是情境，而不是另一项隐藏事件。'});
  add({id:155,short:'体验与有理由宣告',title:'顿悟的体验与理解的根据，是同一回事吗？',subtitle:'保留特殊经历，同时分清它怎样取得理解的地位。',tags:['顿悟','情境','根据'],connection:'第 154 节把问题转向情境；本节说明体验与有理由宣告的区别；第 156 节改用阅读作更细的比较。',translation:['所以，我想说的是：当他突然知道怎样继续、理解了系统时，也许有过某种特殊体验；如果有人问“那是什么样的，突然领会系统时发生了什么”，他也许会像我们上面那样描述它。可是，在这种场合，使他在我们看来有理由说自己理解了、知道怎样继续的，是他具有这种体验时所处的情境。']},{core:'第 155 节保留顿悟可能有特殊体验，但把体验的描述与理解宣告的根据分开。经验可以告诉我们那一刻是什么样，情境则使我们有理由把那一刻称作理解的转折。',coreMore:'这不是体验与现实之间的二选一。作者承认当事人能描述自己的经历，只是否认这份描述独自完成理解的判定。“在我们看来”强调概念在实际评价中的条件，不等于由旁人任意投票决定。',closeReading:[['也许有过某种特殊体验','“也许”说明作者没有规定一项必然伴随所有理解的感觉。理解时可以激动，也可以平静；本节的重点并不在感受强弱，而在它怎样与掌握联系。'],['突然领会系统时发生了什么','这类问题可以正当地要求当事人描述经过。把理解与某种体验区分，并不意味着这份叙述应被排除。应保留它回答的是怎样经历，而非自动回答是否掌握。'],['在我们看来有理由说','理解的宣告可以被理解、接受或纠正。这里谈的是说法的地位和根据，不能简单改写成对内部事件的旁观侦测，也不能化成纯粹主观确信。'],['他具有这种体验时所处的情境','同样的感觉在不同情况下可以获得不同描述。学过方法、能解释并继续的学生，与只感到熟悉却无从下手的人，其宣告的条件不同；这组本站补充比较说明背景如何改变体验的概念地位。']],problem:['我们容易把“我突然懂了”想成一个当事人独享、旁人只能猜测的事件。这样一来，教学、公式和继续都成了外围证据，真正理解却躲在其中。前两节已经显示这一画面如何令人迷乱，本节把改问后的结果重新说清。','体验的特殊性并非假的。一个人可以记得吸气、轻松或公式出现的瞬间，也可以在叙述中突出它。可是，当我们问那是否为理解时，就已经在问这段经历与一项技术、一个问题和继续之间的关系。','“情境”之所以重要，是因为理解不是孤立事件的无条件名称。在同一学习过程中，学生可能先误以为领会，后来发现误解；我们能够说明转变，而不必假定他对自己曾有的轻松感觉也全部记错。'],conceptTitle:'描述经过与说明宣告的资格',concepts:['体验报告与能力宣告可以出现在同一句话里，但承担的工作不同。前者让人知道这件事对当事人是什么样，后者表明他现在能够怎样继续。把两层分开，就能承认第一人称经历，同时保留理解判断可被应用检验的条件。','本站补充：学习地图时，一个人说“现在明白路线了”，可能伴随一幅鲜明路线图。图像是否鲜明，与他是否分得清两个路口并非同一问题。例子不是以行走成功定义全部理解，而是说明同一心理特征不能独自替代实际联系。'],table:{headers:['所问的问题','合适的材料','不能替代的工作'],rows:[['那一刻是什么样','体验与经过的叙述','能力根据的说明'],['为什么说他理解','学习背景与继续','只给感觉命名'],['为什么后来改口','新情况揭示的误解','否认曾有的全部体验']]},argument:['先承认突然领会可以有可描述的体验，保留前面例子的真实性。','再区分体验叙述与有理由宣告理解，使“特殊”不再被当成充分条件。','最后把根据放回情境，由此转向下一节阅读的细密实例，继续比较体验与能力的关系。'],opposition:['本节反对以体验的特殊性作为理解的最终凭据。某种感觉很强烈，不能仅凭强烈就证明已掌握系统。','它同样反对把情境考察说成消灭主观生活。这里恰好给体验留下正当叙述的位置，只限制它独自承担全部解释的责任。'],perspectives:[['从第一人称看','当事人对自己怎样经历有特殊叙述地位，但不能由此推出所有能力宣告永远不会错。这两种地位需要具体区分。'],['从教学评价看','学生的顿悟宣告值得重视，也可以通过继续解释和应用来确认或修正。尊重宣告与停止考察并不是同一件事。'],['从段落衔接看','本节像一座桥，将数列例子中的原则转向阅读。下一节不会寻找读者同样的顿悟感觉，而要比较不同情境怎样应用同一个词。']],cautions:[['不是体验不重要','作者允许人细述体验。否定的是以一次经历的性质无条件决定理解，而非说经历对人毫无意义。'],['不是旁人一定比本人清楚','旁人与本人都可能误判，且各自掌握不同材料。本节没有设立永不出错的外部裁判。'],['情境不是固定核对表','原文并未列一组可机械判断全部理解的必要充分条件。需要逐案展示哪些联系使说法获得地位。']],summary:'特殊体验可以属于顿悟的经过，情境则说明为何我们把这个经过称作理解。'});
  add({id:156,short:'阅读为什么要看情境',title:'读出来的声音相同，就在做同一件事吗？',subtitle:'在熟练阅读、初学拼读、猜测和背诵之间比较。',tags:['阅读','标准','心理机制'],connection:'第 155 节区分体验与宣告的根据；本节以阅读展开；第 157 节追问第一回真正阅读。',translation:['插入对另一个词的考察，这一点会更清楚：这个词是“阅读”。首先必须说明，在这里的考察中，我不把理解所读内容的意义算入“阅读”；这里的阅读，是把手写或印刷的东西转换成声音的活动，也包括按口述写字、抄写印刷文字、按乐谱演奏等等。','在日常生活的情境下，这个词的使用当然是我们极其熟悉的。但它在生活中扮演的角色，也就是我们使用它的语言游戏，即使只作粗略描绘，也很困难。一个人，比如一个德国人，在学校或家里接受了一种我们常见的教学，学会阅读母语。后来他读书、信件、报纸等等。','那么，例如他读报时发生了什么？他的目光沿着印刷词语移动，照我们的说法；他把它们读出来，或者只在心里念。有些词，他把印刷形状作为整体把握；有些，目光抓住前几个音节后便读出；有些逐音节读；个别词也许逐字母读。即使他阅读时既不出声，也不在心里念，只要随后能够逐字或大致复述，我们也会说他读过一句话。他可以注意所读内容，也可以像一台纯粹的阅读机器那样工作，我是说，出声且正确地读，却不注意所读内容；他的注意可能在完全不同的事情上，因此紧接着问他，他也说不出读了什么。','把这个读者与初学者比较。初学者费力地逐字母拼读；但有些词，他凭上下文猜出，或者也许已经把读物的一部分背熟。教师于是说，他不是真的在读那些词；在某些情况下还说，他只是假装阅读。','当我们想到这种阅读、想到初学者的阅读，并问阅读在于什么时，就容易说：它是一项特殊的、有意识的精神活动。','我们也会这样谈学生：“当然，只有他自己知道，他是真的在读，还是只把背熟的话说出来。”（“只有他自己知道……”这类句子，还要再讨论。）','但我要说，我们必须承认：就读出任何一个印刷词而言，那个“假装”阅读的学生意识中发生的，可以与“阅读”这个词的熟练读者意识中发生的相同。谈初学者与谈熟练读者时，“阅读”这个词的应用不同。当然，我们会想说：他们读出词时所发生的，不可能相同。如果差别不在他们当下意识到的东西中，就在心灵的无意识工作或脑中。于是我们想说：无论如何，这里有两种不同机制！其中发生的东西必须区分阅读与非阅读。可是，这些机制只是一些假说，是用来解释、归纳你所观察到的东西的模型。']},{core:'第 156 节用阅读说明：同样读出一个词，乃至有相同的当下意识，都不保证在相同意义上从事阅读。初学者和熟练读者的经历、训练与活动背景不同。把差别立即安放进两个隐藏机制，只是提出一种解释模型，尚未说明词怎样使用。',coreMore:'作者先限定考察范围：这里暂不以理解内容为阅读的必要部分。这个安排使我们能够比较符号到声音、抄写和演奏的转接，不是在给所有日常阅读下一条永远排除理解的定义。',closeReading:[['我不把理解所读内容的意义算入“阅读”','这是方法上的暂时限定。读者若用“读懂一部小说”立即反驳，会忽略作者正在选取哪种工作。另一方面，也不能把这个限定扩成一条语言禁令，说日常的阅读永远与内容无关。'],['只在心里念','熟练阅读并不只有出声形式。作者继续加入不在心里念却能复述的情形，是为了松动把阅读认成一个固定声音事件的想象。列举的目的在显出不同使用条件，不在穷尽所有认知机制。'],['只有他自己知道','这句话被摆成需要继续研究的常见说法，没有直接获得最后权威。作者接着要求承认，当下意识可能相同，而我们对阅读的应用仍不同。第一人称确信不能独自消除概念问题。'],['这些机制只是一些假说','这一句区分描述词语如何使用与解释表现的机制模型。它没有宣布脑科学不可能发现真实差异，而是提醒“必有两套机制”不能仅凭概念差别就被当成已经发现的事实。']],problem:['为什么初学者猜对一个词时可能被说成没有读，而熟练者只看见前几个音节就读出时，却仍算阅读？若只截取当前声音，两者可以一样。词的应用还涉及训练、是否能辨识新词、如何继续等联系。作者借此把上一节的情境要求具体化。','一项活动为我们熟悉，不等于我们已经看清它的全部角色。报纸、书信、乐谱和抄写表明，阅读嵌在多种实践中。想用一个最清楚的初学拼读形象统一它们，可能把局部经验的特征变成不适用于所有实例的标准。','从一个词的正确发声不能直接推断能力，但也不能说正确发声毫无根据。它的分量随场合变化。熟练者偶尔略读和初学者靠背诵蒙对，之所以被不同评价，不必先等到我们检查两人的神经结构才能理解。'],conceptTitle:'同一瞬间为什么不能包办整个活动',concepts:['本节把分析单位从孤立发声扩大到活动在生活中的位置。一个人可以机械地读出一页而不记得内容，也可以慢慢拼读却认真理解。这些差别说明我们需要分清读音、注意、理解内容与阅读能力，不能让其中一个词独占其余词的工作。','所谓机制是对现象提出的解释：例如学习建立了某种连接，使人能从字形得到语音。这可以是经验研究的正当假说，但它的检验需要具体方法。仅说真实阅读必有不同机制，是把一个要证明的解释当成无需检查的概念结论。','本站补充：熟练驾驶者与初学者同样把车停进车位，并不表示两人此刻都在逐条默念操作法。我们可以理解技能差别，而不必先证明两人这一秒意识内容的差异。这个比较只展开情境的作用，不把驾驶与阅读混成同一种技能。'],table:{headers:['阅读场合','可能看到的表现','评价依赖的联系'],rows:[['熟练者略看词首','正确读出整词','长期训练与继续能力'],['初学者背熟课文','同样正确出声','是否借字形辨识新词'],['注意力转移的朗读','读音正确却不记内容','本节暂不要求读懂内容']]},argument:['先明确考察范围，让阅读暂时指一组符号转接活动，避免不同意义的阅读互相代答。','再列熟练者的多种方式，防止把一种初学过程当成阅读的固定心理外形。','随后比较相同发声与可能相同意识，显示词的应用不能仅由此刻事件决定。','最后给隐藏机制的说法恢复假说地位，保留经验研究，也保留对判断条件的概念考察。'],opposition:['本节反对用一种特殊的有意识努力定义全部阅读。努力拼读是明确例子，却不能迫使熟练者一直具有同样体验。','也反对从概念区别直接推出已知的内部机制区别。真实因果研究可以进行，但不能把“应该有”冒充观察所得。'],perspectives:[['从教育看','教师区分猜词、背诵和识字，需要放在教学进展中理解。若把一次正确读音当作全部技能，既可能高估初学者，也可能误解熟练者的省略。'],['从心理学看','注意、内部发声、词形识别可以分别研究。作者的论证不替这些研究给出机制结论，而是警惕以一种假设体验解释所有类型。'],['从语言哲学看','同词在不同场合的应用，可以使用不同标准而仍有联系。这为后面把阅读看成一组家族实例作准备，而不是马上建立一条新总定义。']],cautions:[['不是读懂永远不属于阅读','开头说明只是本次考察的限定。其他用法可以把理解内容放在中心，不能用本段去取消它们。'],['不是熟练者怎样说都算读','情境不等于免检。熟练者也可能背诵或假装，仍需要具体说明此刻为何作这种判断。'],['不是脑机制虚假','假说可能正确，也可能被修正。作者反对的是把模型的身份掩去，宣称仅凭词语区别就已经知道内部发生了什么。']],summary:'阅读的判断依靠活动的训练与情境，不能只由同一瞬间的声音或意识决定。'});
  add({id:157,short:'第一个真正读出的词',title:'开始会读的第一个词，一定能找出来吗？',subtitle:'比较能力变化、体验起点与机器装置的转接。',tags:['阅读','边界','能力'],connection:'第 156 节区分熟练者与初学者；本节追问起点；第 158 节检查把明确起点交给脑机制的要求。',translation:['考虑这种情况：我们把人或其他生物当作阅读机器使用，并为此训练他们。训练者说，有些已经会读，有些还不会。假定一个学生此前没有配合：给他看一个写出的词，他有时发出一些声音，偶尔“碰巧”大致读对。第三者在这样的场合听见他说话，说“他在读”；教师却说：“不，他没有读，只是碰巧。”可是，假定再给他其他词时，他持续作出正确反应。过了一段时间，教师说：“现在他会读了！”那么，先前那个词又怎样？教师应说“我当时错了，他确实读了”，还是说“他后来才开始真正阅读”？他何时开始阅读？哪个是他读过的第一个词？在这里，这个问题没有意义。除非我们作这样的规定：“一个人‘读’的第一个词，就是他第一次连续正确读出五十个词的那一串的第一个词”，或者类似规定。','相反，如果我们把“阅读”用于一种从符号到所说声音的体验，那么谈他真正读过的第一个词就有意义。他可以说：“读到这个词，我第一次有了‘现在我在读’的感觉。”','再看另一种与此不同的情况：一台像自动钢琴那样把符号译成声音的阅读机器。我们可以说：“机器中发生某事之后，某些部件由导线连接之后，它才开始阅读；它读的第一个符号是……”','可是在有生命的阅读机器的场合，“阅读”指的是以某种方式对文字符号作反应。所以，这个概念完全独立于心理机制或其他机制的概念。教师也不能这样谈受训者：“也许他已经读了这个词。”因为对于他做了什么，并没有疑问。学生开始会读时发生的变化，是行为的变化；在这里，谈“新状态中的第一个词”没有意义。']},{core:'第 157 节区分三种起点：能力表现的改变、某种体验的首次出现，以及装置接线后首次运作。不同用法有不同的辨认条件，不能把机器具有可定位的首次运行，直接搬给人的会读能力。',coreMore:'“第一个词”不是永远无意义。原文明确展示体验用法和机器用法中它怎样有意义，也允许为能力评价人为规定门槛。靶子是以为任何用法都天然包含同一条锐利边界。',closeReading:[['只是碰巧','教师的说法根据此前与后续的整体表现，而非否认刚才声音正确。这表明一个孤立结果与稳定能力在评价上不同；不是所有正确反应都自动具有同一概念地位。'],['过了一段时间','这段时间容纳了持续正确的反应。我们据此改变评价，却不必已在每一瞬间作出有或无的划分。承认能力形成并不要求找到一个天然精确的首词。'],['除非我们作这样的规定','五十词门槛是一项可明确采用的规则，而非作者发现的自然分界。规定能够服务评测，却不能倒过来证明此前已潜藏同一边界。'],['对于他做了什么，并没有疑问','这里的难点不是事件记录缺失。我们已经看见正确发声与后续改变，问题在于是否应当把“真正第一次”当成这些事实之外仍待发现的东西。']],problem:['如果一个学生从不会到会，我们很容易要求其间必有一个最早的真正阅读词。作者指出，这个要求可能来自把能力变化想成一只开关的图景，而不是来自能力词的实际用法。','教师先说偶然，后来又说会读，并不必然意味着其中一个判断在同样条件下出错。后续材料改变了我们对能力的评价。能否回溯说早先那次也是阅读，需要看具体说法和目的，而非假定每种判断都必须给出唯一时间点。','机器例子说明确切边界不是被作者禁止。接线前不能运转，接线后首次读符号，我们有具体辨认办法。体验第一次出现也可成为叙述目标。把这些标准与训练场合并列，能看清边界应从何种活动中获得。'],conceptTitle:'人为门槛、体验起点与技能转折',concepts:['规定一项门槛，可以使评测问题精确。本站补充：识字测验可以规定连续答对多少项算通过。通过时刻清楚，并不等于学习能力在心理或生理上必定于那一刻突然完整生成。评价规则与因果变化应分开。','体验可以有第一次，因为当事人是在描述某种感觉何时出现。即使这个记忆可能有误，问题也有可辨认的工作。能力用法则并不需要同一种感觉作为必要部分，不能把前者的时间语法整套移植过去。','原文说独立于机制，是针对这个阅读概念如何确定，并非说学习没有机制。我们能先用训练反应区分会读与不会，再研究形成能力的原因。若把后者当作前者永远必须等待的前提，就会遮住实际语言游戏。'],table:{headers:['“开始读”的用法','辨认起点的办法','不宜强加的标准'],rows:[['训练形成会读能力','观察持续反应的改变','天然唯一的首词'],['第一次有阅读体验','回忆与描述具体感觉','技能也必须同刻形成'],['装置开始运转','检查接线和首次输入','人的能力等同机械开关']]},argument:['先安排一次正确反应却仍被视为偶然的场景，使结果与能力的差别可见。','再加入持续正确与评价改变，追问是否必须找到一个未被规定的首词。','随后展示门槛、体验和装置用法中可明确提问的条件，限制否定句的范围。','最后回到活的受训者，说明行为变化如何已经足以组织这个概念，不必先赋予隐藏状态一条时间边界。'],opposition:['反对每种概念都必须有天然锐利起点的要求。活动发生变化，不等于所有相关说法都以瞬间开关为模型。','也反对把模糊边界当成无从判断。教师能识别进展、纠正错误，也能为特定目的制定标准，而不必先找到所谓绝对首词。'],perspectives:[['从教育评测看','公开规定的通过线有实际作用，但应说明它是为评价而立的线。若把它宣称为能力的自然出生时刻，便混合了不同问题。'],['从技术比较看','自动钢琴式装置的例子给出独立结构标准，因而能谈首次运行。模型有用，却不能只凭像机器就强迫活人具有同样边界。'],['从哲学方法看','作者没有用一个普遍结论结束争论，而是让同一句问话在三种场合中改变工作。理解差别比选出一句绝对答案更重要。']],cautions:[['不是所有首词问题都无意义','体验叙述与装置运行中，原文明确允许这个问题。否定针对的是没有说明标准却强求首词的场合。'],['不是学习没有实际变化','学生的反应确实变化，教师也确实改变判断。缺少天然锐利界线不取消这些可见差别。'],['不是行为主义总理论','本节研究的是特定阅读概念与机制解释的分工，不是证明一切心理词都可被行为定义。']],summary:'会读能力的形成不必天然包含一个唯一首词；要看我们怎样使用“开始阅读”。'});
  add({id:158,short:'脑连接是发现还是要求',title:'更懂大脑，就必然找到阅读的精确开关吗？',subtitle:'区分经验假说与使我们信服的表示方式。',tags:['脑机制','先验要求','假说'],connection:'第 157 节否定训练概念必有天然首词；本节检查脑机制补救；第 159 节转向意识体验。',translation:['可是，这难道只因为我们对脑和神经系统的过程知道得太少吗？如果知道得更清楚，就会看见训练建立了哪些连接；看进他的脑中，便能说：“这个词，他现在读了；现在阅读连接已经建立。”——这大概必须如此，因为否则我们怎么能这么确信存在这样一种连接？这大概是先验地如此，还是只是很可能如此？可能性有多大？问问自己：对这些事情，你究竟知道什么？——如果它是先验的，那就意味着：这是一种对我们很有说服力的表示形式。']},{core:'第 158 节审查一种补救：把阅读的精确起点交给脑内连接。作者要求说明，这是根据具体知识提出的可检验假说，还是仅凭“必须如此”而获得确信的画面。若是后者，确信首先显示表示方式的吸引力。',coreMore:'本节没有否定脑科学能发现学习机制。问题是，尚无具体证据时，为什么已经确信一定存在一个与日常阅读界线完全一致的开关。因果研究的可能性与哲学上预先保证结果不同。',closeReading:[['知道得太少','这项异议把前节困难改造成资料不足。如果困难真是资料不足，就应说清需要何种经验与观察；不能一面承认不知道，一面又保证未来结果必然符合预想。'],['现在阅读连接已经建立','这句话为能力转换配上一个装置模型。但要把模型用于实际大脑，必须提供识别连接和验证关系的办法；模型的可想象性本身并非研究完成。'],['可能性有多大','作者要求把“可能”也从空泛语气改成有根据的判断。不能从没有排除某种机制，直接说这种机制大概存在，更不能再把大概升级成必然。'],['一种对我们很有说服力的表示形式','若所谓先验确信并非来自研究，其内容可能首先是我们偏爱怎样表示变化。承认这一点可以让模型接受比较，而非迫使现实预先保证它。']],problem:['一种概念上不够清楚的要求，常被转交给未来科学：等技术足够先进，就会找到唯一正确边界。这样说有时表达合理研究计划，但若没有具体方法与证据，也可能把原先理想暂存到未来，避免让它接受检查。','学习当然与身体发生的过程相关。本节没有从日常标准推出脑内永远没有可测变化。它只是阻止反向推论：既然我们说学会了，就必须有一个可定位、与每次概念判断完全重合的结构开关。','这里有两种不同责任。机制假说需要由实验支持；概念说明需要展示我们何时说会读。把后者的不锐利当成脑科学尚未成熟，再假定前者成熟后会抹平全部用法差别，尚未给出任何实际论证。'],conceptTitle:'可研究的机制与先加的模型',concepts:['“先验”在本节的作用是揭露确信的来源。若一项关于具体脑连接的主张不依赖任何调查，却已经被看成不可不然，那么我们需要检查它是否只是某种表示的要求。称它先验，并不能使一项经验机制变成不需证据的发现。','有说服力的表示方式不必毫无用途。开关、线路、装置能帮助提出研究问题，组织观察。问题在把它当成现实必须服从的答案，而不允许其他机制、渐变结构或不同层次的概念标准进入。','本站补充：考试成绩连续提高，可以引发关于神经可塑性的研究。可是“哪一秒真正会了”是否有唯一答案，并不能单凭这种研究方向决定。经验研究也可能揭示逐步形成和多重路径，不能事先替它指定必须找到什么。'],table:{headers:['主张形式','应承担的根据','本节的检查'],rows:[['训练建立某连接','具体观察与实验','我们究竟知道什么'],['未来必有唯一开关','预先保证的理由','是不是只在坚持模型'],['连接假说很可能','概率或证据的说明','可能性究竟多大']]},argument:['先完整呈现反驳，使脑机制方案保持最强形态：未来观察可以定位连接建立。','再追问确信来源，将必然、可能、概率与实际知识分开，阻止语气替代证据。','最后说明若确信来自先验要求，它首先属于表示形式，应以模型身份接受比较，而非冒充经验结论。'],opposition:['反对以未来科学的名义替当前缺少根据的哲学要求作保。真实研究尚未开始时，不应已经宣称它的结果必定是什么。','也反对把这种限制读成脑研究无价值。经验模型可以获得支持，甚至揭示精细变化；它们需要履行研究责任，不需靠哲学保证获得权威。'],perspectives:[['从科学方法看','假说的力量来自可区分结果与实际证据。仅说“否则怎么可能”常只表达缺少其他想象，不是已经排除其他机制。'],['从认知模型看','线路模型让某些关系易于想象，却可能遮住渐变、分布和情境差别。这是本站的方法比较，不是作者在此提出某种现代脑理论。'],['从概念考察看','阅读用法的不同标准，不必在一项隐藏结构中被压成单一尺度。解释机制与澄清用法可以分工，而非互相取代。']],cautions:[['不是宣布没有阅读连接','作者没有给出相反的神经学发现。否定一个未经证明的必然主张，不等于证明其反面。'],['先验不等于更高级科学','当具体机制主张只靠先验语气时，应检查表示要求，不能把语气当成实验无法触及的特权。'],['不是机制与行为永不相关','二者当然可以联系。应说明联系如何被建立，不能仅凭概念上想要一条边界就宣称它必在脑中。']],summary:'关于阅读脑机制的确信必须交代根据，不能把一种有吸引力的模型预先当成发现。'});
  add({id:159,short:'本人知道也需要分清',title:'“我知道自己在假装”，证明了什么？',subtitle:'承认读与假装的典型感觉，同时检查它们的地位。',tags:['第一人称','假装','阅读体验'],connection:'第 158 节检查脑机制；本节呈现意识行为作为标准的诱惑；第 160 节将改变体验与实际活动的联系。',translation:['可是，反思时我们容易说：一个人是否阅读，唯一真正的标准是有意识的阅读行为，即从字母读出声音。“一个人总知道，自己在读，还是只是假装读！”——假定 A 想让 B 相信他能读西里尔字母。他把一个俄语句子背熟，再看着印刷词语把它说出，仿佛在阅读。我们当然会说，A 知道自己没有读；他假装阅读时，也感到自己在假装。因为阅读一个印刷句子当然有许多或多或少典型的感觉，不难回想：比如停顿、仔细看、读错，以及词序念起来较顺或较不顺的感觉等等。背诵背熟的东西同样有典型感觉。在我们的例子中，A 不会有那些阅读的典型感觉，倒会有一系列装假的典型感觉。']},{core:'第 159 节让“真正标准是意识行为”的想法取得一个有力例子：背熟俄语却假装识字的人，知道自己在欺骗，也有相应感觉。作者承认这种熟悉场合，同时为下一节检验这些感觉能否担任唯一标准准备材料。',coreMore:'本节不是在结尾突然宣布私人体验永不出错。开头标明这是一种诱惑，后面展示为何它引人信服。必须继续读第 160 节：在那里，阅读与背诵的感觉被有意错开。',closeReading:[['唯一真正的标准','“唯一”是争论的负担。可以承认感觉对当前场景有帮助，而不承认所有阅读判断都必须服从同一种内在感觉。后面的反例正针对这种无条件的独占。'],['仿佛在阅读','这个人不是单纯碰巧说对声音，而是在有目的地制造他识字的印象。背熟句子、望着文字、对他人表演，共同构成我们把它叫作假装的情境。'],['A 知道自己没有读','在这个场景中，第一人称知道非常自然。承认这一点不等于接受“本人在任何情况下都不会误认活动”的普遍原则。熟悉例子的清楚，需要与普遍化的要求分开。'],['或多或少典型的感觉','“典型”不是逻辑上缺一不可。迟疑、顺畅和读错的感受能伴随阅读，也可能在其他活动中出现。原文保留程度词，正不宜把它们改写成不许例外的内心指纹。']],problem:['为什么私人意识的模型比脑机制更令人信服？因为在日常装假场景中，当事人的意图与经历确实起作用。我们能理解他在欺骗，也能理解他知道自己没学过这些字母；不必把这一切当作毫无意义。','但这个清楚例子把许多条件放在一起：不会识字、事先背诵、想让别人误信、表演时看着文字。若把判断仅归给感觉，就会把其他条件的工作抹去，再宣称内心感觉独自解决了全部问题。','作者列阅读与背诵的典型感觉，是让这项诱惑有完整的经验外观，而非简单嘲笑它。下一步需要问：如果这些感觉与活动背景分离，我们还会不会坚持只听感觉的判决？这将由相邻一节的构造情形回答。'],conceptTitle:'清楚的假装场景与唯一标准',concepts:['假装是一种有结构的活动，并非一块隐藏在内心的感觉。A 要制造B的特定信念，为此选择背熟并配合眼神。感受是这个活动的一部分，但离开目标与能力背景，单靠感受名称未必能辨认同一种假装。','第一人称的特殊位置不等于一个万能认识器官。A 知道自己没学字母、准备了背诵，也知道自己想欺骗。这些事实使他的自述有特定根据；它与突然对一种陌生活动作绝不会出错的能力，不是同一主张。','本站补充：表演者按录音对口型，可以知道自己并未发声；这不表示“本人觉得在唱”永远决定所有唱歌判断。这个比较说明一个清楚场景中的自知为何不应直接推广成关于一切活动的理论。'],table:{headers:['例子中的条件','帮助说明什么','不宜直接推广'],rows:[['事先背熟俄语句子','声音来源与字形能力分离','声音正确即可识字'],['意图让他人误信','行为属于装假','假装只是一种感觉'],['典型的阅读与背诵感觉','日常自述为何可信','感觉永远是唯一标准']]},argument:['先提出私人意识作为唯一标准的强版本，明确它的诱惑所在。','再给出一个我们确实愿意承认本人知道的装假情形，让第一人称地位获得具体背景。','随后细数两类典型感觉，使候选标准不只是空名。','最后把问题留给下一节：典型联系若改变，是否仍应由同一感觉独自裁决。'],opposition:['本节所准备反对的是从熟悉装假例子推出全部阅读的私人标准。一个例子清楚，不保证它承载的所有条件都可以只缩成体验。','它并不反对承认当事人知道自己在装假。若为了反对私人标准而把这个普通说法也否掉，就会错过作者比较的起点。'],perspectives:[['从活动分析看','欺骗意图、先前背诵与视觉表演共同组织场景。分析时不能只留下声音和感觉，再把原来的判断原封不动搬过来。'],['从经验描述看','阅读确有顺畅、迟疑等可描述感觉。承认描述的丰富性，比先宣布感觉无用更能准确说明它们究竟承担什么角色。'],['从论证节奏看','本节暂时让一种观点显得有力，随后才改变条件。只摘最后一句作为作者结论，会把提出诱惑与解除诱惑的顺序弄反。']],cautions:[['不是假装者必定焦虑','原文的典型感觉不构成每个欺骗者的必备心理清单。熟练装假也可能没有明显紧张。'],['不是人人都能只凭感觉识别阅读','下一节恰要检验这项推广。不能把“此例中他知道”改成“所有情形中本人体验永远最终”。'],['不要忽略西里尔字母的作用','例子刻意分离会发某句声音与会读字母。若把它换成完全熟悉的文字又不说明差别，就可能削弱原来的对照。']],summary:'假装者的自知在具体场景中清楚，却不足以证明阅读只由一种私人感觉决定。'});
  add({id:160,short:'阅读感与阅读可以错开',title:'感觉像背诵，就一定没有在读吗？',subtitle:'改变体验的配对，再看标准怎样工作。',tags:['阅读','感觉','字母规则'],connection:'第 159 节提出阅读的典型感觉；本节构造体验与活动错开的情况；第 161 节比较连续过渡。',translation:['可是，设想这种情况：我们给一个读得流利的人一篇从未见过的文章。他读给我们听，却感觉自己仿佛在背诵某种背熟的东西；这可能是某种药物的作用。在这种情况下，我们会说他并没有真正读这篇文章吗？我们会把他的感觉当成他是否阅读的标准吗？','或者，给一个受某种药物影响的人一串符号，它们未必属于任何现存字母表；他便按符号的数量说出词，仿佛这些符号就是字母，而且具有阅读的一切外部特征和感觉。（梦中也有类似经历；醒来后会说：“我觉得自己在读那些符号，尽管它们根本不是符号。”）有人在这种情况下会倾向于说，他在读那些符号；另有人则说他没有读。假定他这样把一组四个符号读成或解释成 OBEN（德语“上方”）；再把同样符号倒过来给他，他读成 NEBO（前者的字母倒序），并在后续试验中始终保持相同的符号解释。这时，我们大概会说，他临时给自己设了一套字母表，并按它阅读。']},{core:'第 160 节把典型感觉与阅读活动拆开检验：熟练者可读陌生文章却感觉在背诵；一个人也可面对自造符号而有阅读感。判断需继续查看符号解释是否稳定，而不能只凭一种体验裁决。',coreMore:'药物与梦境是构造对照的工具，原文并未报告某项药理实验。重点是问：当感觉与熟悉活动条件分开，我们愿意如何使用“阅读”？末尾字母顺序的变化尤其显示，规则性应用会改变评价。',closeReading:[['一篇从未见过的文章','这条件排除了通常的预先背诵解释。若文字陌生且读得正确，感觉像背诵并不足以把活动直接改名为背诵。作者用这个安排使第 159 节的典型联系不再包办判断。'],['我们会把他的感觉当成他是否阅读的标准吗','问句检验的是唯一标准的要求。它不是说感觉从此毫无价值，而是要求读者比较感觉与已知文章、能力和当前表现怎样共同起作用。'],['未必属于任何现存字母表','这让第二个例子不再能直接依靠已有识字规则。阅读感和外部形态都在，但我们尚不知道他是不是按照某种稳定关系解释符号。争议因此可以真正出现。'],['始终保持相同的符号解释','一致的应用给出新的判断材料。顺序倒转仍保留逐符号对应，使我们倾向于承认临时字母表。原文保留倾向语气，没有宣布只要有限测试一致就已证明唯一规则。']],problem:['第 159 节的例子把不会读、背熟、装假与特殊感受安排在一起。本节首先分开这些条件：一个人读的确是新文章，然而体验像背诵。如果仍断言没有阅读，就需要说明为何感觉应压倒其他所有已知条件。','第二个例子又换了方向：阅读感并不缺少，可是符号还没有通常字母表的地位。我们是否把这活动叫阅读，不能仅靠当事人有相同体验就立刻定案。问题要走向他怎样处理符号，而非继续把体验说得更强烈。','四符号反转是重要补充。它不是装饰性的拼字游戏，而是让符号与发声之间的稳定对应显现。OBEN 与 NEBO 在这里承担字符排列的比较，学习者不必懂其德语意思，也不应把它们译成两个不同中文词而破坏反转关系。'],conceptTitle:'感受、活动背景与稳定解释',concepts:['一个概念的典型感觉可以在反常场合脱离正常配对。这不意味着正常判断全不可靠，而是提醒我们，熟悉配对与逻辑不可分离不同。我们平常可以据体验作判断，却不能因此宣布任何可能场合都只有这项材料。','“临时字母表”使阅读并不限于沿用某本现成字典。只要能够展示稳定的符号解释，一种新设系统也可能让阅读说法有位置。这里并不主张任何随意发声都算阅读；从无规则回应到保持对应，恰恰是例子中的关键变化。','本站补充：一个熟练打字者在疲劳时觉得自己只是机械重复，但仍能准确录入新材料。感觉的变化值得描述，却不自动取消技能活动。这个比较仅说明体验与活动可能错配，不是在给药物或疲劳的医学机制作结论。'],table:{headers:['构造的情况','感觉提供什么','还要看的条件'],rows:[['朗读新文章','觉得像背诵','材料是否陌生、读音是否对应'],['面对陌生符号','具有阅读体验','是否存在稳定解释'],['符号反转后仍逐一对应','体验可保持相同','临时字母表的应用联系']]},argument:['先在明确的熟练阅读背景中改变感觉，检验背诵感是否足以否定阅读。','再保留阅读感觉却拿掉既有字母表，使相反方向的充分性要求接受检查。','最后加入稳定对应，让评价随具体活动关系而变化，显示规则应用比纯粹体验更能展开这里的判断。'],opposition:['反对把某种阅读感既当必要条件又当充分条件。两种对照分别让这两条要求失去不受检查的地位。','也不主张抛弃感觉或把活动只归结为外部形状。第二个例子正说明外观与感觉都齐全时，我们仍可能需要进一步材料。'],perspectives:[['从标准看','同样一句“他在读”可以根据不同材料被确认或怀疑。作者没有用一项新感觉取代旧感觉，而是改变我们对判断材料的安排。'],['从符号学习看','临时规则可以形成一种可接续的转译活动。这个视角帮助区分造一套新字母表与每次随意喊一个声音。'],['从思想实验看','药物条件不是未经证实的实验报告。它把我们通常绑在一起的因素拆开，检验哪种哲学推论依赖了它们的偶然联结。']],cautions:[['不是在教人用药观察阅读','药物只是原文设定的条件，并无操作建议或疗效结论。不要把概念对照当作医学方案。'],['不是一致几次就证明全部未来','原文说我们会倾向于采用阅读描述。有限表现与全部未来的关系，后文仍会继续考察。'],['字母串无需懂外语','此处应看四个字母如何倒序。它们的词义不是比较的负担，保留符号能让中文读者直接检查原例。']],summary:'阅读感觉与阅读活动可以错开，判断要看具体条件以及符号解释怎样继续。'});
  add({id:161,short:'背诵与阅读之间的过渡',title:'熟悉一串字，为什么仍能阅读它？',subtitle:'从背诵数字到看钟面，注意连续过渡。',tags:['阅读','连续过渡','熟悉'],connection:'第 160 节拆开感觉与活动；本节补上背诵和逐字拼读之间的过渡；第 162 节提出按样本推导的解释。',translation:['还要考虑：从一个人背出自己应读的东西，到他逐字母读每个词、完全不借助上下文猜测或记忆之间，有一串连续的过渡。','试做这样一个比较：说出从 1 到 12 的数列。现在看着钟面，读这串数。——在这个情况下，你把什么叫作“阅读”？也就是说，你做了什么，使它成为阅读？']},{core:'第 161 节提醒，背熟和逐字母拼读不是两只封闭盒子，其间有连续过渡。看着钟面读熟悉数字的例子，让我们询问阅读在这个场合怎样成立，而不是先要求每次都伴随一种完全不同的内在经历。',coreMore:'原文的指令用于概念比较；本站不将它增设为练习。重点在于，即使数字早已会背，我们仍可把看钟面的活动叫阅读。熟悉与阅读可以相连，不能先规定记忆参与便取消阅读。',closeReading:[['有一串连续的过渡','连续性削弱了硬切两类的要求，但没有抹除明确的端点区别。背熟课文假装识字与逐字拼读确实可区分，只是中间情形不必都由同一个绝对尺度判断。'],['完全不借助上下文猜测或记忆','这一端点是刻意纯化的描述。熟练者实际往往利用熟悉度与上下文，因此不能将这个端点直接当作一切真实阅读必须达到的形态。'],['现在看着钟面','钟面给出一种眼前排列，使活动不只是继续口中的数列。即使声音相同，我们仍能进一步描述目光怎样与位置和数字联系。这里的联系不必先化成特殊感觉。'],['你做了什么，使它成为阅读','问法把阅读的工作放回具体活动。它并不保证必有一个可孤立命名的心理动作等着被报告；也可能需要描述你怎样看、按什么顺序、如何对眼前数字作回应。']],problem:['有人或许从装假例子总结：只要用上记忆，就不是阅读。熟悉数字立即使这个总结受阻。我们早会从一数到十二，却仍能读取钟面。这说明记忆的参与与活动是否阅读之间，不能直接作排斥关系。','如果认定阅读必须按每个字母逐一转换，熟练阅读就会显得可疑，因为许多词被整体认出。作者指出连续过渡，是让概念的实际延伸保持可见，不让一个纯化极端审判所有常见用法。','钟面还避免了只讨论同一行文字的局限。位置排列、熟悉数列与目光方向共同组成场合。我们需要说明活动在这里怎样工作，而不是要求当事人从体验中找出一块与背诵绝对不同的内心材料。'],conceptTitle:'明确端点与没有统一中间线',concepts:['承认连续过渡，常被误会为两种活动根本一样。其实连续不取消比较：颜色可以渐变，红和绿仍可清楚区分；本站这个比喻只说明概念关系，不是在解释色觉。背诵与拼读也有明确对照，却不因此需要一条预先适用于所有中间情况的线。','此处的熟悉不只是障碍，也能构成阅读能力。一个常见词越熟悉，我们越不必逐字推算；若把不经推算都叫背诵，就会把熟练阅读最平常的方式排除。需要澄清的是某次活动怎样依靠眼前符号，而非追求消灭全部先前学习。','本站补充：看一个熟悉路牌，司机可能直接认出地点，不在心中逐字拼读。若牌子写错，他仍可能注意并停顿。这类可能回应帮助说明他怎样与眼前符号相接，比仅问是否有背熟感觉更具体。'],table:{headers:['比较位置','记忆怎样参与','不应直接推出'],rows:[['纯粹背熟一段','不依靠眼前词形也可复述','所有熟悉内容都不算读'],['熟练认词','凭训练整体识别','没有逐字拼读便是假装'],['钟面读数','数字与顺序都熟悉','因此必无眼前阅读活动']]},argument:['先把前几节的两极放回连续变化中，避免把对照例子误作永远封闭的分类。','再选择一串极熟悉的数字，使记忆参与不再能被简单排除。','最后通过钟面改变当前活动的条件，邀请读者具体描述何种联系使阅读说法在这里合适。'],opposition:['本节反对为了得到纯粹阅读而排除一切记忆与猜测。这样剥离可能把熟练阅读本身一起排掉。','也反对由连续性断言所有差别都是虚构。明确的背诵和阅读场合仍存在；需要放弃的是一条无需用途说明的万能界线。'],perspectives:[['从技能形成看','熟练化通常减少显性的逐步操作。若把显性操作当成唯一真实技能，就会把掌握得更好误读成根本没有在做。'],['从概念边界看','边界可以因任务而被规定，但规定应说明目的。观察到过渡，不等于概念失效，也不等于任何分类都同样合适。'],['从方法看','一个小变化就能改变问题：同样数列，从说出到看钟面。比较让我们注意活动关系，而不需要先建立一套阅读的隐秘本体。']],cautions:[['不是记忆永远无关','背熟与看字的区别在某些场合非常重要。本节只是说明记忆参与本身不能无条件取消阅读。'],['不是要求每个人报告特殊感觉','原文的问题可能通过描述行为与情境回答，不必假定一定有一项专门感觉被漏看。'],['不是说钟面必定只能读顺序','钟面只是此处的安排。读钟通常还包含指针和报时等用途，不能把这项比较当成钟表使用的完整定义。']],summary:'熟悉和记忆可以参与阅读，连续过渡不要求我们取消实际差别。'});
  add({id:162,short:'从样本推导的解释',title:'把阅读说成“从样本推导”，够清楚吗？',subtitle:'通过对照表展示一种明确的推导活动。',tags:['阅读','推导','规则'],connection:'第 161 节留下阅读怎样依靠眼前符号的问题；本节提出推导解释；第 163 节改变表格使用方式。',translation:['试试这个解释：一个人阅读，是当他从样本推导出再现物。我把他读或抄的文本、据以书写的口述、演奏所用的乐谱等等叫作“样本”。例如，我们教某人西里尔字母表以及每个字母怎样发音；随后给他一篇文章，他按所教的读出每个字母。我们大概会说：他借助所给规则，从字形推导出词的声音。这也是一个清楚的阅读场合。（可以说，我们教了他“字母表的规则”。）','但为什么说，他把所说的词从印刷文字推导出来？除了我们教过每个字母怎样发音，而他随后把词读出以外，我们还知道什么？也许会回答：学生显示出，他借助我们给的规则，从印刷文字过渡到声音。要看他怎样显示这一点，可以改变例子：学生不朗读，而抄写文本，把印刷体转换成手写体。在这里，我们能用表格给出规则：一栏是印刷字母，另一栏是手写字母。他从印刷文字推导手写文字，显示在他查表的做法中。']},{core:'第 162 节提出“从样本推导”的阅读解释，并给出一个清楚实例：学生按照字母对照表抄写。推导在这里通过可描述的查表方式获得内容，而非靠额外假定的一种内在过渡感。',coreMore:'这个实例的清楚不等于已经找到全部阅读的统一定义。下一节会改变对照表的用法，检验“推导”是否只有眼前这一种形式。应先保留实例的明确，再检查不当普遍化。',closeReading:[['试试这个解释','作者暂时采用一个候选，不是立刻颁布最终定义。它回应前面阅读不是单靠感觉的困难，但仍需接受不同用法的检验。'],['从字形推导出词的声音','“推导”表达了一种规则关系，而不只是先看字后出声的时间相邻。要说明这种关系，我们还要展示他怎样根据样本作转换。'],['我们还知道什么','追问把似乎自然的说法重新打开。观察教学与正确出声，可以支持某种描述；但若再声称看见一个纯粹的推导过程，就需要交代多说出的究竟是什么。'],['显示在他查表的做法中','查表让规则应用取得具体形状。我们能描述他找哪一栏、对应哪个符号并怎样抄写。这里不用把推导设成躲在动作之后的第二个事件。']],problem:['“阅读是推导”听来比“阅读是特殊感觉”更客观，但它仍可能只是以一个未说明的词解释另一个词。作者于是追问：怎样知道这里的正确发声是从文字推导，而非背熟、猜中或碰巧？','改成抄写并不否认朗读，而是让规则可以摆在眼前。表格把样本与再现物的对应画出来，查表把使用方式呈现出来。这样，推导不是一个抽象标签，而成为有步骤、可误读、可纠正的活动。','教学历史也是场景的一部分。学生学过字母规则，再据此处理文章，与陌生符号前任意发声不同。但教学并不神奇保证每次结果，本节仍需要展示实际查表，才让某种应用方式清楚。'],conceptTitle:'规则不是摆在桌上就已经被使用',concepts:['样本在这里有多种形式：文字、口述、乐谱。再现物也可能是声音、手写字或演奏。作者把它们并列，不是证明所有感官机制相同，而是让“依据某物转换”的关系显出多个明确用法。','表格的内容与查表的方式需要区分。同一张表可以按同行、错行或不同顺序读取；本节先给出通常的清楚方式，下一节才改变它。若把表格本身当成已经携带唯一应用的对象，就会重犯前面图像强迫用法的错误。','本站补充：把拼音表放到孩子面前，不等于孩子已知道如何找对应项。教师还需示范检索、纠错和继续。这个例子说明规则记号与熟练使用的差别，不是在给所有识字教学规定一种必经程序。'],table:{headers:['转换场合','样本','怎样让规则应用可见'],rows:[['朗读','印刷字母','说明所学发音规则与实际回应'],['抄写','印刷体文字','查表后写对应手写体'],['演奏','乐谱','按谱面约定处理音符与节奏']]},argument:['先给出推导候选，并在字母教学后朗读的情景中看到它的合理性。','再追问这种说法是否比教学与发声的已知事实多添了一项未经说明的过程。','随后把朗读改成抄写，使对应规则成为表格，实际使用成为可描述的查表方式。','以一个清楚实例暂时安顿词的工作，同时为下一节比较其他应用方式留下空间。'],opposition:['本节反对以抽象的推导名称替代说明。若不能显示怎样依据规则，再换一个词也没有使阅读更清楚。','它并不反对用规则说明阅读。清楚的查表例子就是正面材料；限制的是把这个局部形式立即当成全部实例的隐藏本质。'],perspectives:[['从教学看','示范如何查表与交出一张表不同。理解规则包括怎样把样本用于具体转换，而不只是看过规则文本。'],['从规则关系看','“根据”不是单纯的先后关系。一个输出跟在输入后面，并不自动构成从输入推导，需要在活动中说明联系。'],['从哲学方法看','用一项可综观的活动澄清词义，比假定不可见过渡更有方向。清楚来自实例的组织，不来自更庄严的术语。']],cautions:[['不是每次阅读都必须查表','熟练者可以不查表而读。此处是为显示规则使用而选择的例子，不能当作所有阅读的必要条件。'],['不是因果机制无关紧要','学习怎样改变身体可以另行研究。本节说明的是推导这一描述怎样在活动中获得内容。'],['不是已经证明统一定义','“试试”保留了检验位置。下一节正会提出变式，不能把本节候选提前冻结成最后结论。']],summary:'“推导”要靠具体的规则应用获得内容，表格与查表给出一个清楚实例。'});
  add({id:163,short:'同一表格可以怎样读',title:'应用方式变化，“推导”就失去意义了吗？',subtitle:'从错行抄写到逐次变化，考察边界。',tags:['推导','表格','规则变化'],connection:'第 162 节给出通常查表；本节改变查法并追问边界；第 164 节以洋蓟比喻回应本质搜索。',translation:['可是，假如他查表时总把 A 抄成 b、B 抄成 c、C 抄成 d，依此类推，把 Z 抄成 a，怎么样？我们也会把这叫作根据表格推导。可以说，他不是依照第 86 节的第一个图式，而是依照第二个图式使用它。','一种可以用毫无简单规律的箭头图式表示的做法，大概也仍是根据表格的推导。','可是，假定他不坚持一种转写方式，而按一个简单规则改变：一次把 A 抄成 n，下一个 A 抄成 o，再下一个抄成 p，等等。那么，这种做法与无规律做法之间的界线在哪里？','可是，这难道意味着“推导”这个词其实没有意义？因为当我们追究它的意义时，意义似乎消散得无影无踪了。']},{core:'第 163 节展示，按照同一表格推导可以有不同路径，甚至路径本身也能按规则变化。边界变得难以统一描述，不等于“推导”没有意义；它让我们检查为何先要求一个适合所有实例的单一内核。',coreMore:'这里的例子不是说任何混乱输出都算推导。作者先给出我们愿意承认的变式，再把变化推向难以判断的区域。末尾是一个需要回应的疑问，不是已经宣布概念崩溃。',closeReading:[['也会把这叫作根据表格推导','错开一行并未自动取消与表格的关系。我们能够描述这条新路径，因而可以理解它怎样仍根据同一材料转换。它可能不符合教师任务，却仍可在另一意义上叫推导。'],['毫无简单规律的箭头图式','没有简单规则，不等于没有可给出的对应图式。一套复杂箭头仍能规定怎样找项。这里需要分开复杂性、不可描述与完全无规则，不能把它们混作一种否定。'],['按一个简单规则改变','这次连对应方法都变化，但变化仍可说明。例子提醒我们，规则并不只表现为每次同一输入永远得到同一字母；还可以包含序号与先后等条件。'],['其实没有意义','末尾反问展示一种哲学恐慌：找不到纯粹核心，就认定原来词语是空的。下一节将说明，这可能只是剥离实例时把工作条件也一起剥掉的结果。']],problem:['上一节查表很清楚，容易让我们误以为推导必定是同一行的固定配对。本节首先移动配对，让同一材料产生另一套可以说明的使用。清楚的典型实例不再能独占全部概念。','教师可能说学生抄错了，而哲学比较仍可以说他按另一图式推导。这并不矛盾：前者评价是否完成指定任务，后者描述怎样利用表格。若把任务正确性与有没有规则关系混在一起，就看不清例子的作用。','随着路径更复杂、应用方式会改变，我们可能无法指出一条天然界线。困难由此转向：为什么一切有意义词都必须先具备统一边界？如果这个要求只是预设，边界问题就不能立即宣布概念失效。'],conceptTitle:'规则的层次与边界的要求',concepts:['一种转写规则可以以字母为条件，也可以以出现次数、前一项或某种图式为条件。这里不是鼓吹无限解释，而是提醒：判定实际使用哪种规则，要看活动怎样展开，不能只看静止表格长什么样。','第 86 节已经通过箭头展示表格的不同读法。本节借那个图式说明，记号自身不会包办应用。它并不要求读者会某种复杂形式逻辑，而是使表格与路径这个直观差别重新进入比较。','本站补充：数据转换程序可以给每第二条记录附加不同标记。输出随次数变化，不代表程序没有规则；但是否实际按该规则工作，仍需检查程序与运行条件。这个例子说明复杂与无规则的区别，不能替原书制定一切推导的算法定义。'],table:{headers:['表格使用方式','可描述的联系','仍需区分'],rows:[['固定错一行','沿另一配对路径','推导关系与任务答对'],['复杂箭头图','明确但不简单的对应','复杂与无规则'],['每次改变转写','变化受出现次数控制','变化规律与任意跳动']]},argument:['从通常配对移动到错行配对，保留表格关系却改变结果。','再把路径复杂化，区分没有简单规律与完全不能说明。','随后让方法本身按规则改变，把固定对应的预设也松动。','最后呈现概念无意义的忧虑，等待下一节检验这忧虑依赖的本质要求。'],opposition:['反对把一个清楚实例的外形强加给所有推导。规则应用可以有可比较的多种形式，而非只能重复同一配对。','也反对以边界不锐利为理由宣布概念全无意义。不能给所有可能情形划定一条天然线，不等于日常明确实例无法被说明。'],perspectives:[['从规则使用看','表格不是自动发出结果的装置。人怎样读取、遵循哪条路径，是解释的一部分，不应被静态符号遮住。'],['从正确性看','一项做法可以有规则却不符合当前命令。把规则性与完成任务的正确性分开，有助于理解学生错法而不必认可它。'],['从概念方法看','逼近边界应当帮助看清不同用法，而非成为撤销全部用法的理由。作者借连续变式暴露了一项未受审查的要求。']],cautions:[['不是一切都算推导','原文提出边界问题，没有把所有随机反应纳入。复杂可描述的联系与完全没有可接续联系仍需比较。'],['不是错抄也符合原任务','换一种图式可叫推导，不表示已经遵照教师指定方式。描述与评价可以同时成立。'],['反问不是作者最后判决','“没有意义”是被引出的恐慌。第 164 节将通过洋蓟比喻回应，不能只停在反问上。']],summary:'推导的多种规则形式和不锐利边界，并不自动取消这个词的实际意义。'});
  add({id:164,short:'剥掉叶子就没有洋蓟',title:'寻找纯粹推导，为什么反而把推导弄丢了？',subtitle:'特殊实例不是遮住本质的外衣。',tags:['家族相似','本质','推导'],connection:'第 163 节从边界不清引出意义消散的疑问；本节以洋蓟回应；第 165 节再次检验阅读体验。',translation:['在第 162 节的场合，“推导”这个词的意义清楚地摆在我们面前。但我们对自己说：这只是推导的一个极特殊的场合、一种极特殊的装扮；要认识推导的本质，就必须脱去这层装扮。现在，我们剥去特殊外衣，推导本身却消失了。——为了找到真正的洋蓟，我们把它的叶子剥光了。因为第 162 节的确是推导的一个特殊场合，但推导的本质并不是藏在这个场合的外表之下；所谓外表，本来就是推导这个实例家族中的一例。','同样，我们把“阅读”这个词用于一个实例家族。在不同情境下，我们用不同标准判断一个人是否阅读。']},{core:'第 164 节指出，意义仿佛消失可能是搜索方法造成的：我们把具体实例的工作条件当成可剥掉的外衣，结果连活动一起删去。推导和阅读可以由实例家族联结，不必靠藏在各例后面的纯粹内核统一。',coreMore:'洋蓟比喻不是说概念分析没有用。它让我们检查某次抽象究竟删除了什么：若删掉之后活动无从辨认，就不能自动宣称终于接近更深本质。需要回头看被删的条件是否正承担了词的工作。',closeReading:[['意义清楚地摆在我们面前','清楚的起点没有消失于生活，而是在哲学搜索中被判成不足。作者先提醒第 162 节确实给出明确推导，再检查为何我们执意从它后面找另一物。'],['必须脱去这层装扮','“必须”标出预设：特殊条件一律只是外衣，真正本质必定独立于它们。原文要审查的正是这个要求，而非接受它后继续抱怨研究工具粗糙。'],['把它的叶子剥光了','洋蓟不是叶子包住的另一颗真正洋蓟。比喻让“去掉一切具体性”不再天然等于深入。它针对某种本质模型，不能推广成所有对象都不可能有内部结构。'],['在不同情境下，我们用不同标准','这句话给出正面方向：比较一组相关实例及其判断条件。不同不等于任意，标准仍要放回实际活动解释，而非由个人临时宣布。']],problem:['在第 162 节，我们能看见学生查表，能说明样本和抄写的关系。为什么还会感到真正推导没有被说到？因为我们已经要求一种不依赖任何具体形式的统一核心。实例越具体，越被判成仅仅表面。','依照这个要求剥离时，我们去掉表格、查找、转写、教学与应用，最后却不知道还在谈什么。消失未必证明原词没有意义，也可能证明这些被剥离的材料原本就在提供意义的使用条件。','阅读例子同样如此。读报、拼读、演奏、背熟的比较，不是等待一种内在事件替它们统一的杂乱外壳。它们自身的联系与差别可以构成我们理解这个词的材料，而不必先被压成同一心理过程。'],conceptTitle:'实例家族如何替代隐藏内核',concepts:['家族不是所有成员具有同一个特征的集合。它可以由多种交叠联系维系：都按样本转换的活动、都使用某种表格的活动、都体现熟练识别的活动等。具体联系需要分别说明，不能把“家族相似”当作省去分析的新口号。','不同标准也不代表一个词被任意改变。在识字教学中，辨识新词可能重要；在熟练者默读中，后续复述可能足够；在装置用法中，结构连接又有作用。标准之所以不同，要由活动目的、背景和实际实践来解释。','本站补充：把一把伞的布、骨架和开合关系逐项去掉，再问真正的伞在哪里，可能是误把构成条件当作遮挡物。这个比喻不证明伞概念也必须家族化，只帮助区分寻找结构与删掉全部工作条件。'],table:{headers:['本质搜索的动作','可能失去的材料','本节建议'],rows:[['删除具体查表方式','怎样从样本转写','保留实例的实际工作'],['排除不同判断条件','为什么此处说正在读','比较场合中的标准'],['只准一种共同心理事件','多种相关活动的联系','考察实例家族的结构']]},argument:['先恢复第 162 节的清楚，指出后来迷乱不能自动推翻最初的正常实例。','再重建剥离步骤，让读者看见特殊形式怎样被预先判成遮挡物。','借洋蓟比喻说明，删除所有具体条件并不保证留下一个更真正对象。','最后将推导与阅读并列为家族概念，让调查回到各例联系和判断条件。'],opposition:['反对凡特殊皆外衣、凡本质皆藏在下面的思路。具体条件可能正是活动能被识别的构成材料。','也反对把家族结构当作拒绝精确研究的借口。每个清楚实例仍可详细描述，特定任务也可以制定明确标准。'],perspectives:[['从概念分析看','抽象应让关系更清楚，而非一味删除差别。若分析末端只剩一个无法应用的空位，应回头检查删除的条件。'],['从教学看','学生可以通过多个实例掌握阅读，教师也可据不同阶段采用不同标准，不必先教一个统摄所有情况的心理定义。'],['从方法连续性看','本节把早先游戏的家族相似用到推导和阅读。比较的是统一方式，不是断言阅读在生活中就是娱乐游戏。']],cautions:[['不是所有概念都无法定义','技术上可以规定精确规则。作者反对把一种本质模型无条件强加到这里，而非取消一切定义。'],['不是不同标准永不冲突','具体情形仍会争议，需要继续说明。家族一词没有自动裁决所有边界个案的权力。'],['不是洋蓟证明全部哲学','比喻只照亮一种剥离错误。它不是一条可替代任何具体论证的普遍定律。']],summary:'不要把使实例能够工作的条件全剥掉，再把剩下的空白当作意义本身。'});
  add({id:165,short:'词音以特殊方式出现',title:'阅读的词音“自己溜进来”，就是它的本质吗？',subtitle:'检验一种令人信服的内在描述。',tags:['体验','阅读','特殊过程'],connection:'第 164 节把阅读看作实例家族；本节让特殊体验的异议重新发声；第 166 节检查声音究竟怎样出现。',translation:['可是，我们想说，阅读毕竟是一个十分确定的过程！读一页印刷文字，就能看见：那里发生某种特别而且极有特点的事情。——那么，我读印刷文字时发生什么？我看见印刷词语，说出词语。但这当然不是全部；因为我可以看印刷词语、说出词语，却不是阅读。即使我说出的，正是按某套现存字母表应从那些印刷词语读出的词，也仍可能不是阅读。如果你说阅读是一种特定体验，那么你是否按人们普遍认可的字母表规则阅读，就全然不要紧。','所以，阅读体验的特点在于什么？我想说：“我说出的词，以一种特殊方式出现。”不是像我编造词语时那样出现。它们自行出现。但这还不够，因为我看着印刷词时也可能偶然想到一些词音，却没有读那些文字。我还可以说，所说的词并非像某件事让我想起它们那样出现。例如，我不会说，印刷词“无”总让我想起声音“无”。毋宁说，阅读时，所说的词仿佛自己溜进来。的确，我甚至无法看一个印出的母语词，而不发生一种独特的内部听见词音的过程。','〔附注〕“一种十分确定的……”这个表达的语法。（气氛。）','人们说：“这张脸有一种十分确定的表情”，然后寻找能描写它的词。']},{core:'第 165 节重新呈现特殊体验的诱惑：阅读词音仿佛自行溜进来，不像编造或回忆。作者让这种描述逐步接受检查，显示“特殊”“自行”尚不足以承担阅读的统一说明。',coreMore:'这段包含被考察的第一人称声音，不宜把末句的内部听见直接当成最终定义。附注对“十分确定”的提醒也表明：确信有特点，与已经说明特点是什么，并非同一工作。',closeReading:[['阅读毕竟是一个十分确定的过程','这是一项重返的要求。此前家族分析并未消除它的吸引力，所以作者继续追问确定到底体现在哪里，而不是仅用一句家族相似让异议闭嘴。'],['这当然不是全部','看字并说出正确声音，尚不能包办阅读判断，这点被保留。但不足不自动要求一个纯体验补丁；前文已经说明，更广的情境也可能承担差别。'],['它们自行出现','不费力、非刻意编造的特征很熟悉，却不是阅读专属。词音也可以在看字时偶然浮现，因此自动感还没有给出充分条件。'],['寻找能描写它的词','附注中的脸部表情提醒：说“十分确定”可能只是表达我们觉得有某种特点，并非已找到一项可辨识的共同属性。词语的确定语气不能代替具体描述。']],problem:['明确用例仍可能引发一种剩余感觉：既然亲自读一页就知道发生了特别的事情，为什么还要比较这么多背景？作者没有否定这份熟悉感，而是要求它说清自己究竟说明了什么。','描述经过三次收紧：不是单纯看与说，不是像编造那样出现，也不是任意想到或受提醒后回忆。每次排除都需要具体比较，不能只凭更强烈地说“很特别”取得定义。','末尾内部听见在熟悉文字中确实可能自然发生，但前文还包括抄写、按谱演奏等用法。若从一页熟悉印刷文字的经验直接推出全部阅读的本质，就再次把局部清楚当成普遍统一。'],conceptTitle:'描写熟悉体验与提出统一解释',concepts:['“自行出现”可以描述熟练化的某一面。它不必是一种完全独立、每次相同的感觉对象。一个人说词自己来了，可以是在比较刻意搜索、艰难拼读和自然朗读的差别，而非报告读到一个叫作自行的内心部件。','“特定”也有语法工作。我们可以在尚未能明确说出的情况下强调一种表情很有特点。若将强调当成已掌握本质的证明，就把说话人的确定姿态与对象的完整分析混淆。','本站补充：熟练写下姓名时，笔画也可能像自己流出；临时涂鸦也能不费思索地产生。自动感可以帮助描述差别，但仍需活动的技能与目的背景才能区分签名、练字和随手划线。'],table:{headers:['候选特征','它抓住什么','为何尚不够'],rows:[['看字并说词','外部动作的次序','背熟者也能这样做'],['词音自己出现','熟练阅读的省力','偶然联想也可自发'],['内部听见词音','某种母语阅读体验','不能直接覆盖全部阅读家族']]},argument:['先让统一过程的要求再次出现，使论证面对真实诱惑而非稻草人。','依次检查看与说、非编造、自行出现等候选，保留其描述作用并限制其充分性。','把“溜进来”和内部听见推到最鲜明处，为下一节的逐字比较准备材料。','附注再从表情用法检查确定语气，防止以强调替代说明。'],opposition:['反对以一项极熟悉体验的鲜明程度作为普遍定义的保证。熟悉说明我们有材料，不说明材料只容一种解释。','也不反对精细描写阅读体验。作者自己不断修正描写，只是让每项描写接受比较，而非获得免检地位。'],perspectives:[['从经验描述看','省力与刻意思索可有可描述差别。认真描述这些差别，与声称一切阅读必有同一种内在质料，是不同层次。'],['从技能看','熟练活动常不需逐步指挥。自动性可由训练与活动背景理解，不必每次都再加一项名为自动的特殊事件。'],['从词语语法看','“十分确定”可以表达尚待展开的辨认要求。它不是一个已经兑现的定义，附注使这个差别可见。']],cautions:[['不是否认内部发声','许多人读字时可以内部发声，本节没有宣布它虚假。应限制的是它的普遍解释资格。'],['不是任何自发词音都算阅读','原文明确提出偶然想到词音的反例，正说明自发还不足以区分活动。'],['不要把第一人称末句单独立为结论','下一节继续追问特殊方式；本节尚在展开与检验一种看法，不能截取末句终止调查。']],summary:'熟悉的自行词音可以被描写，却尚不能独自说明阅读这个概念的全部工作。'});
  add({id:166,short:'声音究竟怎样出现',title:'说一个字母时，能找到特殊的“出现方式”吗？',subtitle:'在熟悉字母、陌生符号与习惯之间比较。',tags:['熟悉','自动反应','阅读'],connection:'第 165 节说词音以特殊方式出现；本节拆开字母作比较；第 167 节回到整页印刷文字的熟悉结构。',translation:['我说过，阅读时，所说的词“以一种特殊方式”出现；可是以什么方式？这是不是一种虚构？看单个字母，注意字母声音怎样出现。读字母 A。声音怎样来的？我们根本说不出什么。现在写一个小写拉丁字母 a！书写时的手部动作怎样出现？和前一比较中的声音不同吗？我看着印刷字母，写出手写字母；除此以外，不知道还能说什么。','现在看这个符号 ![](images/30px-Par._166.png)，随意想到一个声音并说出来。我想到声音 U，却不能说，它出现的方式与前者有本质区别。差别在稍有不同的情境：我先前对自己说，要想到一个声音；声音出现前有某种紧张。我也没有像看见字母 U 那样，自动说出 U。这个符号不像字母那样为我所熟悉。我带着一点对其形状的兴趣看它，仿佛有些紧张；我想到一个倒过来的西格玛字母。','再设想，你现在必须经常把这个符号当字母使用；你习惯于看到它就发一个确定的声音，例如德语字母组合 sch 所表示的音。我们还能说什么，除了过一段时间后，一看它，这个声音便自动出现？也就是说，看它时，我不再问“这是什么字母”，也不会对自己说“看到这个符号时，我要发 sch”，更不会说“这个符号以某种方式让我想到 sch”。（把这与另一观念比较：记忆图像靠一个特殊标记区别于其他想象图像。）']},{core:'第 166 节检查词音出现的“特殊方式”，发现我们往往能说明情境、熟悉和训练的差别，却说不出一项独立的出现质地。陌生符号经过习惯也能引发自动声音，这使特殊体验的统一解释需要重新考虑。',coreMore:'作者没有证明所有发声的神经过程完全一样。比较针对我们怎样描述经验，以及什么材料使阅读与临时想声音不同。说不出一种本质质地，不等于事实没有任何差异。',closeReading:[['可是以什么方式','这句要求给前节的特殊补上具体内容。若回答只是再次强调它很特别，就仍未说明与其他声音出现有什么可辨认的区别。'],['差别在稍有不同的情境','作者转而列举先前的指令、紧张、熟悉与形状兴趣。它们不是被取消的外围噪声，而是实际能说明这两个活动差别的材料。'],['这个声音便自动出现','经常使用可以使陌生符号获得熟悉反应。自动性不需要由一种永恒字母本性来解释；字形与音的联结可以在训练与实践中建立。'],['记忆图像靠一个特殊标记','末尾是比较提示，不是另立一套记忆理论。它提醒我们，同样可能把一种概念差别误想成内部图像自带的小标签，需要检查其实际辨认条件。']],problem:['阅读之特殊似乎在亲自读一个字母时最容易看见。但当被问声音究竟怎样出现，我们可能只能重复“看了便读出”。这不使阅读消失，却使原来声称已经掌握特殊方式的解释失去内容。','陌生符号安排改变了活动。人先接受“想到一个声音”的指令，再注意形状并发声；熟悉字母则通常无需这项安排。两者的区别可以从过程背景描述，不必另找一种声音出现时共有的内部标签。','习惯形成又改变比较结果。陌生符号反复用作字母后，也能得到自动反应。若先前把自动出现当成不可学习的阅读本质，这个过渡便难解释；若看训练与用法，变化则能具体展开。'],conceptTitle:'自动性、熟悉度与指令背景',concepts:['自动并不是没有任何条件。熟练读字的反应依赖学过字母、常见符号和当前活动。省略显性的自我命令，不等于一项脱离历史和情境的神秘发生。反过来，有意识注意一个熟悉字母，也不必因此停止阅读。','“sch”在自译中只是标出一个音，不要求读者学习德语。原文用一个发音作为假定约定；中文读者需要把握的是符号经常使用后能稳定引出该音，而不是该音本身有什么哲学特殊性。','本站补充：初学某个键盘快捷键时会自言自语，熟练后直接按下。没有默念不使操作丧失规则，初学时多一份紧张也不构成另一种永远隔绝的动作本质。这个比较只照亮习惯变化，不把阅读还原为键盘动作。'],table:{headers:['场合','能够说明的差别','不宜预设'],rows:[['熟悉字母 A','通常直接发音','必有独一心理质地'],['陌生符号前想声音','先有指令、注意与紧张','差别只能在声音内部'],['符号经常作为字母使用','形成熟悉自动反应','字母天生携带固定音']]},argument:['把前节整词描述缩小到单个字母，追问特殊方式能否被指明。','加入书写动作与陌生符号，比较不同活动中我们实际能够说出的差别。','让陌生符号经过训练成为熟悉字母，显示自动反应与习惯的关系。','最后用记忆图像的类比提醒，概念差别不应轻率改写成内部对象自带的标记。'],opposition:['反对把“特殊方式”当作不需具体说明的最终解释。若所谓特点不能在比较中获得内容，强调再多也不等于已经描述。','也反对否认所有心理差别。原文承认紧张与兴趣等经验，它要求的是分清可描述的实际差别与额外要求的本质标签。'],perspectives:[['从学习看','习惯能够改变反应的熟悉程度。把训练历史放回分析，比要求所有熟练反应都附带一次当前指令更符合例子的结构。'],['从经验考察看','不能报告某种质地，并不证明所有物理过程相同。语言上的说明责任与神经学结论需要分开。'],['从图像误导看','记忆小标签的提示，与前文理解幕后过程同属一个方法主题：先检查我们为何期待内部标志，再决定是否真有需要研究的具体假说。']],cautions:[['不是说一切自动行为都是读','自动发音只是一个特征，仍须看符号规则与情境。原文没有用自动性取代旧的体验定义。'],['不是发音约定任意就无规则','约定可以不同，一旦进入实践仍有正确与错误的使用。新符号例子保留稳定发音的要求。'],['不是声称所有过程完全一致','作者说自己不能指出本质的出现差异，不是宣布脑和身体中毫无可研究差异。']],summary:'阅读的差别常在熟悉、指令与训练情境中可说清，不必都藏在词音出现的一种特殊质地里。'});
  add({id:167,short:'整页文字为什么如此熟悉',title:'阅读的统一感，能否由熟悉的活动来理解？',subtitle:'比较印刷页、摩尔斯码和反复出现的字形。',tags:['熟悉','印刷文字','体验'],connection:'第 166 节比较单个字母的声音；本节回到整页文字的熟悉结构；第 168 节将继续检查体验描述。',translation:['那么，说阅读是“一个十分确定的过程”，究竟有什么道理？这大概意味着：阅读时，总有同一个确定过程发生，我们可以认出它。可是，如果我一回读一个印刷句子，另一回根据摩尔斯电码写字，真的发生同一个心理过程吗？','另一方面，读一页印刷文字的体验，当然有某种一致性，因为活动本身就是一致的。它不同于看着任意线条随便想到词语，也很容易理解。仅是一行印刷字的样子就极有特点：字母大小大致相同，形状也有亲缘，反复出现；词语大部分不断重复，熟悉得如同熟悉的脸。想想一个词的拼写改变时，我们感到的不适；也想想拼写问题曾引起的更深感受。当然，不是每种符号形状都深深刻入我们心中。例如，逻辑代数中的一个符号可以换成任意另一符号，而不激起深厚感受。','要记住，我们对看见的词形的熟悉，与对听到的词音的熟悉，程度是相近的。']},{core:'第 167 节把阅读的统一感放回活动的熟悉结构：反复出现的字形、相近大小、熟悉词语和长期习惯，都能使读一页印刷文字有稳定面貌。它不必因此与摩尔斯码等所有阅读用法共享一个同样的心理过程。',coreMore:'作者既保留统一性，也限制统一性。一个明确活动内部有一致体验，与整个阅读家族由同一内在事件统一，不是同一个主张。不能因反对后一主张，就把印刷页的鲜明感受也说成不存在。',closeReading:[['总有同一个确定过程发生','作者把含混强调变成可检查的强命题：每一种阅读都发生同一心理过程。这样才能看清它与印刷句子、摩尔斯码等不同活动如何相合或冲突。'],['活动本身就是一致的','一页文字的阅读有稳定结构，体验的相似不必全由一个隐藏内核解释。书写格式、反复出现的词和熟练活动，已经提供了可以比较的材料。'],['熟悉得如同熟悉的脸','熟悉不是抽象的知道名称，而是反复交往中形成的辨认与反应。比喻使视觉词形的深度熟悉获得直观位置，避免把它看成声音背后无关的外壳。'],['不是每种符号形状都深深刻入我们心中','作者防止又一次普遍化。常用文字与逻辑代数记号可以有不同情感地位；符号都能替换的技术事实，不保证替换对人的生活毫无差别。']],problem:['如果看一页书有鲜明统一感，我们容易以为自己由此认识了阅读的共同本质。本节要求把范围说准：这份一致感可能正属于这种经常进行、形式稳定的活动，不必涵盖所有也叫阅读的情形。','印刷句子与按电码写字的并列，承接第 156 节的广义考察。若只想到通常默读，便会觉得所有阅读理应有相同内部词音；把其他实例放回来，就能看见统一过程的要求还没有得到证明。','词形像熟悉面孔的比较，让我们注意平时被忽略的背景。行列、大小、字体相似和重复词，不是哲学分析可先行删除的偶然包装。它们参与形成此类阅读活动的稳定面貌。'],conceptTitle:'局部一致与全部实例的共同过程',concepts:['局部一致可以很强，而仍不是全部家族的本质。看报的人常有熟悉节奏，读新代码的人却可能逐项停顿。本站补充这个对照只说明活动差异，不能替原文经验地断言每个人必有什么感觉。','拼写改变造成不适，并不说明旧拼写有永恒逻辑优越性。它显示视觉词形在生活中被训练和熟悉的深度。相反，一些技术记号可轻易替换，也不说明所有符号都只是一层可以无代价撕掉的外衣。','视觉与听觉熟悉被并列，有助于纠正只把声音看成活语言、把文字看成死符号的倾向。本节没有建立完整文字理论，只提醒我们别忽略看见词形本身已经承担的生活联系。'],table:{headers:['比较对象','可见的一致或差别','不宜推出'],rows:[['一页印刷文字','字母大小亲缘、词反复出现','所有阅读共享同一心理过程'],['拼写改变','熟悉形态被打断的不适','旧拼写逻辑上不可更改'],['逻辑代数符号替换','有时不激起深厚感受','全部文字都可无代价替换']]},argument:['先把“特定过程”的说法展开为同一心理过程的要求，再通过不同阅读形式检验它。','随后承认印刷页阅读确有一致性，避免把否定普遍化误作否定经验。','详细摆出页面形式和词形熟悉，使体验的稳定有了可比较的生活背景。','最后限定形状熟悉的范围，并把视觉与听觉熟悉并列，保留差别而不强求同质。'],opposition:['反对从一类熟悉活动的统一体验跳到一切阅读的共同本质。范围从本例扩大到全部，需要独立说明。','也反对把文字形式仅当作可随意换掉的死外壳。技术上能替换与生活中毫无感受差别，并非同一结论。'],perspectives:[['从文字经验看','页面并不是一组任意线条。长期接触使词形成为熟悉材料，能够帮助说明阅读与临时造声音的不同活动背景。'],['从规范与习惯看','拼写规范可以调整，但改变可能触动熟悉反应。承认习惯力量不等于证明规范永恒，也不等于所有不适都构成反对改革的理由。'],['从方法看','作者把统一感分配到具体活动，而不是直接驱逐它。这种做法既承认经验，也限制从经验到普遍定义的跳跃。']],cautions:[['不是所有人都对拼写有同样情绪','原文描述熟悉联系的力量，不是提出一条没有例外的心理定律。具体反应仍需看人和场景。'],['不是文字比声音更根本','末句把二者的熟悉程度并列，不是建立单向优先关系或取消它们的差别。'],['不是否认阅读有共同关系','批评的是唯一共同心理过程的要求。实例仍可通过多种相似、训练与用途连成家族。']],summary:'阅读的统一感可以来自具体活动与词形的深度熟悉，不必是所有阅读共享的隐秘事件。'});
  // 逐节展开特定论证，不将某一实例提升为所有阅读的统一机制。
  const depth = {
    156:[
      '可以更仔细比较教师的两种评价。对初学者说“这个词你只是猜出来”，往往是在检验他能否独立处理不熟悉的新词；对熟练者说“他扫了一眼就读出”，则可以依靠已经建立的识字背景。两者并非同一次动作因身份不同而被任意改名，而是相关材料不同：初学者也许在换一个词后立刻停住，熟练者则可以在整段材料中继续。这里所举的可能回应为本站展开，不是原文逐项规定的必要条件。它帮助我们看到，判断依赖的联系可以超出正在发声的那一秒，又不必被想成另一个同时发生的心理对象。',
      '不注意内容的正确朗读尤其重要。若我们把阅读解释成“意识到正在提取意义”，这位朗读者似乎必定被排除。但原文已经说明，本次使用不把理解内容作为中心。所以，当一个人随后无法回答文章说了什么时，这可能表明他分心，并不自动证明刚才没有读出文字。概念之间可以有关系，又不必完全重合。读音准确、注意词形、理解意思和记得段落，可以在具体生活中组成不同组合。把其中某种组合挑为真正阅读，再把其余正常组合判为幻影，便重复了理想先行的要求。',
      '还应区分关于某一个词的比较，与关于整项技能的比较。作者允许两人在读出任何一个词时具有相同意识，并未因此说他们一生的训练或全部能力都相同。从局部相同不能推出整体相同，从整体不同也不能反推每一秒的体验必定不同。这个范围差别使隐藏机制的要求失去表面上的逻辑强迫力。研究者当然可能发现不同机制，但必须通过经验建立；不能以“他们一位真读、一位假读”这一概念区别，直接证明那一瞬间一定有两种独立可定位的脑装置在工作。'
    ],
    157:[
      '“也许他已经读了这个词”在这里为什么不能解决问题？因为它容易把已知的反应重新包装成一项未知内部状态：嘴里已经发出什么声音，我们知道；后来是否持续正确，也有记录；现在却要求在这些之外再查明是否有一个叫作真正阅读的状态发生。作者不是禁止对学习程度保留不确定，而是在指出本例没有给这种额外状态规定独立工作。若一份档案只是缺少当天表现，当然可以补查；若档案完整，而我们仍要求找到自然选出的第一词，就需要检查这个要求来自哪一种阅读用法。',
      '五十词规定有一个经常被忽略的后果：它能把原本不锐利的评测问题变清楚，却也引入了可替换的选择。我们可能为另一任务规定二十词或不同难度，标准的用途随之变化。这样得到的第一个词属于测验制度，而不必是隐藏机制开启的第一个词。承认制度可以规定，并不意味着规定任意或毫无根据；词数可以由教学目标和误判成本说明。需要拒绝的是把一项有用途的决定伪装成无需决定就早已存在的自然界线。',
      '最后的行为变化也不应被压缩成眼前某次动作。持续正确的反应、接受纠错、处理新材料等，是在时间中展开的联系；作者本例直接提供的是一串越来越稳定的正确回应。把这种整体变化称为行为，不等于把活人当成没有心理的空壳。它只是说明这个训练游戏怎样组织会读和不会读的判断。若另一个研究项目提出内部连接，那将增加一种机制解释；它不能反过来抹去最初已经使我们能够辨认教学成功的实践条件。'
    ],
    158:[
      '这里可以把三句貌似相近的话分开：“一种连接可能解释阅读能力”“我们已有证据支持这项连接”“没有这项连接，阅读在逻辑上就不可能”。第一句是提出候选，第二句报告支持程度，第三句给出不可不然的要求。作者的追问正针对它们之间未经说明的滑动。研究前景可以令人期待，但期待不是证据；一种机制容易想象，也不自动有很高概率。若说自己已经知道必定存在，就需要交代这份知道如何获得，不能等到被问证据时又退回只是在设想。',
      '连接模型还可能混合两种精确性：测量可以把某种生理变化定位到很短时段，但“在这一时刻开始真正会读”是另一个使用上的判断。二者可以因一项具体研究定义而联系，例如研究者明确采用某种测试标准；然而这种联系不能凭借精密仪器的威望自然完成。假使实际机制是渐变而且依任务改变，也不能仅因没有找到哲学预设的单一开关就宣布研究失败。这些是本站为澄清模型责任所作的展开，并非原文已经确立的现代神经学结果。',
      '本节结尾不是要我们把一切都改叫主观表示，从而放弃真伪。相反，它要求先弄清主张的身份。若是表示方式，我们可以比较它照亮哪些关系、遮蔽哪些情况；若是经验假说，我们可以研究哪些观察支持或反对它。只有把身份说清，批评才有明确对象。把模型宣称为不可违背的事实，又在缺少证据时以先验为护栏，会使两种检查同时失效。作者把确信还给表示形式，正是让它重新成为可考察的东西。'
    ],
    159:[
      '西里尔字母例子有一个信息上的不对称：B 可能只看到像朗读的表演，A 却知道事前的背诵安排。这个差别已足以使“他知道自己在装假”显得自然，不必再假定A通过观察一种独一的假装感觉才得知自己的计划。感觉可以伴随这项自知，但不是唯一能够说明自知的材料。若把准备历史、意图和不识字的情况全部删除，再保留“只有他知道”作为纯体验权威，就改变了原例，而没有说明改变后为何仍应维持同一判断。',
      '典型感受的清单也不是一条诊断公式。迟疑可能来自初学拼读，也可能来自临时忘词；顺畅可能来自熟练阅读，也可能来自熟背。眼睛仔细看，既可能是辨认字母，也可能是刻意扮演辨认。把这些可能联系摆出来，并非说任何感觉都无法辨别，而是让感觉的角色随具体情境获得说明。我们可以在熟悉场合信任它，却不必因此授予它无条件的必要充分地位。下一节的反常情形，会把这项区别推到更明显的位置。',
      '本节还有一个阅读声音与内容知识的分离。A 背的是一个俄语句子，但例子不要求他懂这句话的意思；他要伪装的是能读字母的能力。若中文读者把它误解成不懂内容所以没有读，就错过了第 156 节的范围限定。这里的区别在能否借字形取得相应声音，而非是否能解释句义。把这一层说清，也能看出作者为何选择陌生字母表：它让背熟声音与掌握文字规则之间的落差格外容易看见。'
    ],
    160:[
      '两种构造在逻辑上方向相反。第一种让本来愿意叫作阅读的活动失去常见阅读感，因而考察感觉是否必要；第二种让常见阅读感全部保留，却使符号关系暂不清楚，因而考察感觉是否充分。如果只记得“感觉有时会错”，就没有读出这个安排的细度。作者不是把一份报告简单宣布为错误，而是问当报告与其他条件改变配对时，我们的词怎样继续工作。这样的比较不必以谁拥有一个终极观察位置为前提。',
      '末尾倒序的安排是逐符号对应的可见化。OBEN 在德语中意为“上方”，但此处不靠词义起作用；NEBO 是前者字母的倒序，不是需要学习的另一个中文概念。相同四符号反过来时，输出也按对应次序反过来，使临时字母表的解释得到支持。如果他无论看到什么都说原来声音，评价就可能不同。本站在这里展开的是原例检验的工作，不能由此推出任何四次一致便已经逻辑证明全部未来都会照做。',
      '梦境的括号还说明，强烈的阅读感不必自动提供稳定字母系统。醒来后说“仿佛读了”，并不是在否认昨晚曾经有那种体验，而是在重新描述体验与符号活动的关系。这与熟练者读新文却感觉背诵形成呼应：关于经历怎样的描述，可以保留；关于活动是哪一种的判断，则需要更多联系。这样区分，可以同时避免两种粗糙结论，一是体验决定一切，二是体验既不决定一切便毫无意义。'
    ],
    161:[
      '钟面比较里的声音可以完全相同，因此不能用发声结果独自区分两次活动。但这也不要求我们补上一项专门的内部动作，仿佛只有第二次偷偷按了阅读按钮。眼前的数字排列、目光是否随它移动、遇到一个不同数字会怎样回应，都可能让说明更具体。这些本站展开的比较方向，帮助我们看出当前样本在做什么。它们不是原文规定的统一测试，也不保证每个实际钟面例子都没有争议；作用是把问题从内心标签转回活动联系。',
      '连续过渡还提醒我们，所谓纯粹两极往往是为了比较而选出的。逐字母读且绝无猜测或记忆，是一个便于看清差别的端点，不必是每个真实阅读时刻都能完全符合的记录。若因为这个端点最清楚，就以它审判中间全部情形，我们会把模型当成现实必须服从的偏见。这与前面简单语言游戏的比较方法一致：例子可以照亮关系，但不能仅凭它简单明白，就宣布其余用法需要被改造成它。',
      '同样，记忆参与也有不同程度与角色。它可以是把整篇声音背熟，与眼前字形无关；也可以是记得字母规则，以便辨识从未见过的组合；还可以是对常见词的整体熟悉。若一概把记忆叫作阅读的对立面，就无法解释为什么学过字母的人反而更会读。区分这些角色不需要假设每种记忆都有一种可隔离的内心质地，而需要看它在具体任务中怎样与样本、错误与继续相接。'
    ],
    162:[
      '本节的推导不是形式逻辑中由前提推出定理的狭义演算。作者举的还有抄写、听写与按谱演奏，因此中文读者应把它理解成根据样本与规则产生相应再现的活动。这个范围本身已经提示多样性：样本可以是看见的文字，也可以是听见的口述；结果可以是声音，也可以是笔画。若把其中一种感官路线当成统一内在过程，就会把原本为了比较而扩大的实例重新压窄。需要保持的是各例中可说明的依据关系，而非先宣布它们具有同一心理质料。',
      '表格例子有两层可见性。第一层是规则记号可见：两栏让我们知道怎样的对应正在被提出。第二层是应用可见：学生查表、定位并抄写，显示他怎样把对应用于任务。只有第一层而无第二层，我们仍不知道学生如何继续；只有输出正确而无其他背景，我们也未必知道他为何这样写。两层并列，使“他推导了”不必再充当一项神秘事件的报告。它可以是在一个已安排清楚的活动中，概括这些彼此相连的步骤。',
      '这也解释了为何作者愿意暂时承认一个清楚实例，而不是因日后会出现边界就拒绝它。哲学上的不清楚往往不是实例本身不工作，而是我们要求它同时承担一切可能情况的说明。先看清这个学生如何使用这张表，能够提供一块可靠的比较材料；随后再改变路线，才能准确知道哪些联系被保留、哪些发生变化。若一开始就只有“任何事情都可能解释”，便既无法说明通常应用，也无法理解下一节的变式为何值得注意。'
    ],
    163:[
      '变化转写方式的例子包含一种嵌套：每一次的输出可以不同，而怎样变换输出又有一个相对简单的说明。这个结构使“有规则就必定每次相同”的直觉需要修正。可是，承认这点也不能倒过来说任何输出序列都已经显示一项规则；事后可以编一个公式描述有限结果，与当事人如何实际使用表格，并不是同一个问题。我们还需要把解释放回教学、查找、纠错和继续中，看它是否确实组织了这项活动。',
      '原文的边界问题不是在索取一条永远不许有争议的数学线，而是在展示这种索取如何使概念显得消失。随着例子逐步远离最初的同行配对，我们仍愿意承认若干用法，却越来越难给出一次性覆盖全部的条件。如果因此直接宣布没有意义，就已经把意义等同于先有天然边界。这个前提正需要检查。明确实例的可用性与边界个案的可争议，可以并存；前者不会只因后者出现就被撤销。',
      '本站补充一个对照：把一份名单每次向后移动一位，与每次随手乱填名字，可以在相当清楚的场合区分。两者之间还可能存在更复杂、难以一眼识别的做法。看不出规律可能是资料不足，也可能是并没有此处需要的规则联系，不能仅凭外观立即决定。这个补充帮助保留实质差别，同时拒绝简单与有规则、复杂与无规则之间的直接等号。作者并未要求我们把所有复杂做法无条件接纳为推导。'
    ],
    164:[
      '洋蓟比喻中最关键的不是一种蔬菜的植物学，而是寻找者对层次的预设。他认定真正对象在里面，外面各片只是暂时遮住它；所以每去掉一片，都觉得自己更接近目标。直到什么都不剩，才发现所谓外部与内部的划分可能从开始就用错了。理解这个结构，能把比喻准确用于本节的推导，而不必把它扩大成“所有本质都不存在”的一般形而上学。针对某种剥离策略的批评，并不会自动解决所有概念应如何定义的问题。',
      '这段对家族的运用也给解释者一项责任：不能只写“阅读是家族相似”，便省去各项比较。应当展示什么联系使读印刷文字、抄写和按谱演奏能够一起讨论，又是什么差别使它们采用不同标准。例如，音准在演奏中可能重要，抄写字形则有另一种纠错方式；这些差别不是应当掩盖的缺陷，正是认识各活动的材料。若用家族相似把所有差别盖住，就会把反对单一本质的方法再次变成一种空泛的统一口号。',
      '本节也能帮助区分抽象与遗忘。抽象可以为某个目的暂时忽略字母颜色或纸张材料，让对应路径更清楚；遗忘则是在作普遍结论时，忘了这些省略只是为了一个目的。并非凡被忽略者都无关，也并非凡具体者都必须永远保留。关键在于说明为什么省略不损害当前问题。作者要撤回的，是一种不看用途便不断剥离的要求；保留下来的，则是可以逐步交代选择理由的比较工作。'
    ],
    165:[
      '从开头到内部听见，读者可以看到一种不断修补定义的努力。先说看字并发声，遇到背诵反例；再说词自行出现，遇到偶然联想反例；接着排除提醒式回忆，最后转向极熟悉的内听经验。这个推进并不证明每项描述都虚假，而是显示描述的排除力总需要比较来确认。若一遇反例就把特点改称更微妙、更不可言说，定义便可能不再给出可检验的差别，只保留解释者坚持确有本质的态度。',
      '字母规则在本节中暂时被体验观点说成不要紧，也应放在论辩语气中读。作者不是取消阅读的规则关系，而是在指出：如果坚持阅读仅是一种独立体验，那么按照哪套人们承认的规则，就不该再有决定作用。这个后果让体验说的负担显出来。前文对稳定字母解释的重视，并没有突然被作者放弃；两种材料并列，正是为了看清体验模型是否真的能够保留我们在具体活动中已经采用的差别。',
      '附注中的表情比较又给这场修补提供一面镜子。“他有一种十分确定的表情”可以合理表达辨认和寻词的状态，但其中的确定并不是已经写下定义的同义词。我们接着寻找词，是因为描述还未完成。阅读的特殊气氛也可能如此：它标记一种需要展开的熟悉经验，而不是完成了一项对全部实例都充分的解释。把寻词中的确信与定义成功分开，能够让我们尊重经验，又不让它提前结束概念调查。'
    ],
    166:[
      '书写小写字母的插入，使比较不再局限于声音。我们同样可以问，手部动作究竟以何种特殊方式来到；当事人可能仍只能描述看了印刷字母、写出手写字母。这个对照并非以粗略外部描述证明内心没有任何过程，而是让原先“我当然知道其特殊出现方式”的承诺接受兑现。描述者发现自己能明确说出的主要是对象、任务和行动关系，就应该承认说明目前落在这些关系上，而不是把尚未说明的独特性当成已经把握的实体。',
      '陌生符号的形状兴趣也有具体作用。它让人不再像面对熟悉字母那样直接过渡，而会把符号当图形观看，想到倒过来的希腊字母。新符号反复用作字母后，这种观看方式可以退到背景。这里改变的不是纸上的形状突然长出一个音，而是人同它交往的方式发生变化。以此理解习惯，就无需假设每一次稳定发音都必须先在心内重说规则；习惯可以表现在反应怎样继续，而不只是规则句子如何被默念。',
      '末尾记忆图像的提示还可以谨慎展开。我们有时以为，记忆不同于想象，必定是图像内部多出一种特殊质感或标签。作者这里只邀请比较，没有证明所有辨认都只依外部背景。对阅读的启示在于：一个概念差别也许靠较宽的联系获得工作，不该先假定任何差别必在孤立图像中占一个位置。若确有可描述的感受差别，仍可以描述；若没有，不能仅凭期待便宣布它隐藏在更深处。'
    ],
    167:[
      '本节对一行印刷字的细描，也示范了所谓描述怎样具有哲学目的。大小、形状亲缘与反复出现，本来都不是新发现；但把它们重新并列，就能削弱一种误会：阅读的统一感似乎全来自一个不可见事件，与眼前材料和生活习惯无关。作者没有用新奇经验击败这个误会，而是让早已熟悉的条件重新获得注意。这里的描写不只是文学装饰，它改变了统一感应当从哪里得到说明的方向。',
      '印刷文字与任意线条的差别也不只是物理复杂度。任意线条可能画得很整齐，文字也可能潦草，但后者可以同一套长期训练的识别与回应接上。原文特别强调反复熟悉，正让这种生活联系进入视野。我们因此不应仅根据线条外观给阅读下一条机械定义，也不应把熟悉当作躲在视觉后面的神秘感觉。熟悉可以通过会辨认、会继续、会察觉异常等关系展开，同时保留它对当事人具有的鲜明经验面貌。',
      '逻辑代数符号的可替换性，最后为本节再加一道范围限制。某个技术符号的形状不牵动深厚情感，不代表它没有规则作用；一个常用词的拼写改变令人不适，也不证明它的旧形式在逻辑上不可更改。两者都能有规范，但它们进入生活的方式不同。把这两种关系同时保留，才能避免在冷冰冰的任意记号与不可替代的内在本质之间二选一。符号的用途、熟悉和情感联系可以交叠，而不必被压缩成同一条尺度。'
    ]
  };
  for (const [id, paragraphs] of Object.entries(depth)) {
    window.ESSAYS[id].problem.push(paragraphs[0]);
    window.ESSAYS[id].concepts.push(paragraphs[1]);
    window.ESSAYS[id].argument.push(paragraphs[2]);
  }
  const qualifications = {
    158:'因而，对“必须如此”的回应也不是一句“未必”就足够。还要指出必须的根据在哪里被省略，哪个经验判断被改写成先验要求，以及这种改写怎样影响我们对先前能力概念的理解。本节的连续追问正是在展开这些省略，不能只摘其中一句当作怀疑一切科学的口号。',
    159:'在这个场合承认 A 知道自己装假，也不要求 B 永远无法识破。B 可以换一个新句子，或问一个字母怎样读。本站补充这种可能互动，是让第一人称与第三人称的差别保持具体：各自掌握的材料不同，并非一道永远不可跨越的内外墙。因此，“只有他知道”在某次交谈中可有自然作用，却不应被升级成一条把所有实际检验排除在外的形而上学原则。',
    160:'本节还保留意见可能分歧的地位。有人愿说陌生符号前的活动是读，有人不愿，这不是作者遗漏了唯一答案，而是让我们看到这个新场合尚未像普通印刷文字那样被既有用法固定。稳定解释随后加入，便提供进一步比较。承认这种过渡性的犹疑，与宣布一切判断都没有根据不同；新的材料可以使说法更有方向，即使没有一条先天法则替我们预先裁决。',
    161:'把原文的比较保留为分析材料，也能避免另一误会：似乎每个读者只要亲自看一眼钟面，就会收到一种绝对可靠的内心答案。作者的问题并未承诺这种结果。有人可以说自己的目光随数字移动，有人只觉得机械复述，有人发现不易给出区别；这些不同回应恰好还要放回活动比较，而不是由其中某份感觉独占定义权。原文的指令不提供私人验真仪器。',
    162:'“显示”也不等于对内心的一次透明摄像。学生可以公开查表，却偶尔走错栏；教师可以看到应用方式，却仍需进一步教学。可见的活动足以让解释有内容，并不表示所有判断都因此不可出错。作者所要求的清楚，是能指出正在谈哪种联系、错误可以在哪里发生，而不是为一切未来表现提供绝无例外的保证。如此理解，查表例子既保留明确性，也不需要变成一套排除全部疑问的哲学基础。',
    163:'对这个学生，我们还可以问“你现在是每次向后移一格吗”，或者要求他示范下一项。这样的交谈把规则当成可以教、可以解释和可以纠正的实践材料。它不必总能立即解决边界情况，却使判断具有继续的方向。与之相反，只问表格本身真正蕴含哪一种唯一读取法，会忽略人实际怎样使用它。规则的公开说明与训练，不是等候内在本质发现后才准进行的临时办法。',
    164:'“外表”一词在此被加以审查，并不表示凡外部可见者都比内部真实。作者改变的是解释次序：先承认这个实例确实是推导，再看它与其他实例的联系；不要先宣布所有可见细节只是遮挡，随后又责怪意义藏得太深。这种次序的调整，让具体描述获得正当地位，也避免以另一个更深实体的许诺，不断推迟本来可以开始的澄清。',
    165:'还可以问，“想起”与“读出”之间的比较究竟排除了什么。看见一个地名而想到朋友，是一类联想；看见这个地名而读出它，是另一类活动。两者都可能自发，也都可能熟悉，但它们如何回应改字、如何与上下文接续、是否按字形取得声音，并不相同。这些本站补充的差别不构成统一定义，却显示一个形象动词不能独自完成全部工作。“溜进来”使经验生动，仍需与其他用法联系，才说明这里为什么是阅读。把形象的力量承认为描述力量，便无需把它额外提升为直接看见本质的能力。正因为这份描述可以继续追问，它才有哲学用途；若把它宣称不可分析的最后事实，比较工作反而会在最需要开始的地方被截断。',
    166:'原图在这里是比较对象，不是一段需要翻译的外文。读者只需看出它对当事人陌生，可能让他想到一种倒转形状。随后约定某个声音，展示的是熟悉怎样形成。换一个同样陌生的符号，比较也可以进行；但保留底本图示能避免由解释者擅自更换形状而改变原例。图像的来源与它在论证中的作用，应当同时清楚，而不必赋予这幅图独一无二的哲学意义。',
    167:'因此，原文末句不应读成视觉词形在头脑中必定有一份与听觉完全一样的副本。相近的是熟悉程度，不是感官材料被证明同质。我们能对一个常见词的样子和声音都很熟悉，二者仍有不同的使用方式与辨认条件。保留这个差别，恰好符合本节拒绝以一种统一心理过程吞并全部活动的方向，也让印刷页的鲜明特征不被内部声音一项材料独占。'
  };
  for (const [id, paragraph] of Object.entries(qualifications)) window.ESSAYS[id].concepts.push(paragraph);
})();
